INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('0ac122e6-a760-4401-9fb3-db4ce4f46688', 'GERAK GULUNG BUDI DAYA TI PADJAJARAN', 'gerak-gulung-budi-daya-ti-padjajaran', 'GERAK GULUNG', 15, 'KABUPATEN BOGOR', '/uploads/perguruan-2d3e7140c9deb413100f42221bde5c4e7b27bce7-1555x1556.png', 'ALM. MUHAMMAD RIDWAN', NULL, '<p><strong>Gerak Gulung Budi Daya (GGBD)</strong> adalah aliran silat tradisional warisan Kerajaan Padjajaran yang berpusat di Bogor. Berbeda dengan konsep perguruan umum, GGBD mengutamakan prinsip kekeluargaan di mana tidak ada istilah "Guru dan Murid", melainkan "Kakak dan Adik".</p>
<p>Fokus utama aliran ini adalah pembinaan akhlak dan silaturahmi. Selain jurus utama, GGBD juga mencakup varian permainan seperti <em>Gerak Leang</em> dan <em>Gerak Sambut Pukul</em>. Keanggotaan bersifat sakral dan harus melalui proses <em>Taleq</em>. Saat ini, pelestarian ilmu diteruskan oleh para <em>Rakawira</em> (pelatih resmi) yang telah diberi izin.</p>', '<p>Awalnya, aliran ini bernama <strong>Gulung Maung</strong> yang bersifat tertutup dan sangat mematikan (<em>kembangna cilaka, buahna pati</em>) dengan tokoh awal Eyang Sarean. Perubahan besar terjadi pada masa <strong>Eyang Guru H. Abdullah</strong> (1800–1916). Melalui hasil <em>istikharah</em>, beliau mengubah nama menjadi Gerak Gulung Budi Daya dan memperhalus gerakannya—mengambil inspirasi dari gerakan shalat dan fase tumbuh kembang manusia—sehingga tidak lagi sebuas karakter harimau pembunuh.</p>
<p>Ilmu ini kemudian diwariskan kepada <strong>H. Ace Aom Kusumaningrat</strong> dan keluarganya, termasuk pengembangan jurus khusus wanita oleh Ibu Tresmen Megantara. Pada masa <strong>Horis Kusumaningrat</strong> (1930-1999), GGBD mulai dibuka untuk umum setelah sebelumnya hanya diajarkan di lingkungan keluarga. Sejak itu, banyak praktisi beladiri yang datang berguru, dan tradisi ini kini dilanjutkan oleh murid-murid senior (Rakawira) seperti Kang Iyus, Mas Heri, Kang Awang, dan Kang Dani.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('0e3ed7e7-2b0d-4bea-b050-db4e278c66b6', 'KARUHUN PADJADJARAN CIMANDE SAHBANDAR', 'karuhun-padjadjaran-cimande-sahbandar', 'CIMANDE, SYABANDAR', 150, 'KABUPATEN BOGOR', '/uploads/perguruan-2ca3a77ee42757b9d72fe34efa158ac6dcadda82-1555x1556.png', 'AGUS SUPRIYOKO', '62818612911', '<p><strong>Perguruan Karuhun Padjadjaran (KPCS)</strong> adalah wadah pelestarian seni bela diri yang memegang teguh filosofi penghormatan terhadap warisan nenek moyang. Nama perguruan ini memiliki makna mendalam: <em>"Karuhun"</em> berarti leluhur dalam bahasa Sunda, dan <em>"Padjadjaran"</em> merujuk pada kebesaran Kerajaan Pakuan Padjadjaran di Jawa Barat.</p>
<p>Secara esensi, perguruan ini dimaknai sebagai semangat pengakuan terhadap para leluhur pencipta karya seni bela diri, di mana para anggotanya berperan sebagai generasi penerus yang wajib menjaga dan melestarikan warisan budaya tersebut.</p>', '<p>Perguruan ini didirikan atas inisiatif dan kesepakatan tiga orang pendekar utama, yaitu <strong>R. Agus Supriyoko</strong>, <strong>Yusuf Sarwo Edi</strong>, dan <strong>Suparto</strong>. Ketiga tokoh ini meletakkan dasar berdirinya KPCS sebagai sarana untuk meneruskan estafet keilmuan dan tradisi silat leluhur.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('19ff00ab-4439-4527-8515-aa2d86d9b6f9', 'PENGSIMATOGA', 'pengsimatoga', 'JALAN ENAM', 150, 'Depok', '/uploads/perguruan-949036b3d58a8749d7fca549d140acbd2187e84a-500x500.png', 'Yadi Haerudin', '08118712838', '<p>Pengsimatoga (Perguruan Pencak Silat Jalan Enam) adalah perguruan silat yang berbasis di Depok, Jawa Barat, berfokus pada pelestarian tradisi, pembentukan karakter mental tangguh, dan jiwa mandiri. Perguruan ini aktif dalam kegiatan sosial, menjaga kebersihan lingkungan, dan memprioritaskan pendidikan akademik bagi para pesilat mudanya di samping keterampilan bela diri.</p>', '<p>Pengsimatoga merupakan bagian dari kekayaan silat Betawi/Depok yang berakar pada aliran Jalan Enam, sebuah aliran yang mengutamakan kelincahan langkah dan teknik pertahanan diri praktis. </p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('3f23e64c-e244-4cd6-9440-a33c4f9625ae', 'PADJADJARAN NASIONAL', 'padjadjaran-nasional', 'CIMANDE', 100, 'KABUPATEN BOGOR', '/uploads/perguruan-a4e0e072a819473485c4b817846705f8ed9434d5-1555x1556.png', 'TATANG SUPRIYATNA', NULL, '<p><strong>PPSN Padjadjaran</strong> adalah perguruan silat yang menjunjung tinggi empat aspek utama: Seni Budaya, Beladiri, Olahraga, dan Mental Spiritual. Filosofi perguruan berlandaskan pada motto <em>"Silih Asah, Silih Asih, Silih Asuh"</em> dengan kode etik pesilat <em>"Asih, Budi, Bakti, Sakti"</em>.</p>
<p>Secara teknis, perguruan ini mewarisi aliran <strong>"Jurus Lima" (Panca Dirya)</strong> yang terdiri dari: <strong>Cimande</strong> (Cai Iman Hade), <strong>Sera</strong> (5 jenis serah), <strong>Syahbandar</strong>, <strong>Cikalong</strong> (tenaga lembut), dan <strong>Depokan</strong> (permainan bawah). Gerakan jurusnya diyakini diciptakan oleh para Wali, seperti Pangeran Rangga Gading, Pangeran Papak, hingga Pangeran Jaka Sembung.</p>', '<p>Perguruan ini didirikan pada <strong>12 Desember 1928</strong> di Desa Sukaraja, Bogor oleh <strong>K.H. Raden Ahmad Karta Kusumah</strong>, yang kemudian diteruskan oleh <strong>Tubagus Moh. Siddik Sakabrata</strong>. Pada tahun 1979, perguruan mencatat prestasi gemilang ketika atlet-atletnya (terutama dari cabang Jakarta dan Bogor Barat/Cigudeg) berhasil menembus kejuaraan tingkat Nasional hingga Asia.</p>
<p>Prestasi inilah yang mendorong perubahan nama menjadi <strong>Perguruan Pencak Silat Nasional (PPSN) Padjadjaran</strong>. Pasca wafatnya Guru Besar pada tahun 1997, kelestarian organisasi dilanjutkan oleh inisiatif <strong>Bapak Tb. Ukay S.</strong> selaku sesepuh, yang memastikan pengembangan seni budaya dan regenerasi perguruan tetap berjalan, khususnya di wilayah Bogor Barat.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('4ba417ec-2896-4ba6-b042-0fa0e35241a7', 'SERA JAGA LAWANG', 'sera-jaga-lawang', 'SERA', 87, 'KABUPATEN BOGOR', '/uploads/perguruan-7ca6b17a8287b5f8c466038f1c9c8c20389f01f1-1555x1556.png', 'DASWARA SULANJANA SH', '6287711047980', '<p><strong>Perguruan Silat Sera Jaga Lawang</strong> merupakan sebuah lembaga pendidikan seni bela diri tradisional yang berdedikasi melestarikan warisan budaya pencak silat, khususnya aliran Sera. Perguruan ini berpusat di wilayah Kabupaten Bogor, dengan padepokan yang berlokasi di <strong>Perumahan Bukit Sakinah, Kecamatan Leuwiliang</strong>.</p>
<p>Sebagai wadah pembinaan karakter dan fisik, perguruan ini memiliki struktur organisasi yang jelas untuk menjamin keberlangsungan pelatihan dan regenerasi pesilat. Saat ini, kepemimpinan Perguruan Silat Sera Jaga Lawang dipegang oleh <strong>Ibu Ratnawati</strong> selaku Ketua Umum, dengan bimbingan dan arahan langsung dari <strong>Bapak H. Daswara Sulanjana</strong> yang menjabat sebagai Dewan Pembina. Keberadaan tokoh-tokoh ini menjadi pilar utama dalam menjaga nilai-nilai luhur dan tradisi keilmuan yang ada di dalam perguruan.</p>', '<p>Perjalanan sejarah <strong>Perguruan Silat Sera Jaga Lawang</strong> memiliki akar tradisi yang kuat dan sanad keilmuan yang jelas. Secara garis keilmuan (<em>nasab</em>), perguruan ini mewarisi aliran <strong>Silat Sera Bogor</strong> yang bersumber dari <strong>Bapak H. Cucu Sutarya</strong>.</p>
<p>Dalam rekam jejak historisnya, perguruan ini merupakan pengembangan atau pecahan dari <strong>PS Pancassera</strong>. Eksistensi keilmuan dan kiprahnya pun telah diakui secara formal sejak lama. Hal ini dibuktikan dengan keaktifan perguruan bergabung di bawah naungan <strong>Ikatan Pencak Silat Indonesia (IPSI) Kota Bogor</strong> sejak sekitar tahun <strong>1970-an</strong>.</p>
<p>Hingga kini, Perguruan Silat Sera Jaga Lawang terus menjaga orisinalitas jurus dan filosofi aliran Sera, sembari terus beradaptasi dengan perkembangan zaman di bawah manajemen kepengurusan yang baru di Leuwiliang, Kabupaten Bogor.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('6LuKmvfZQ3bDFShaI1QWkb', 'DHARMA BUDAYA', 'dharma-budaya', 'CIMANDE', 65, 'DRAMAGA', '/uploads/perguruan-34bf304926be67f085d63179c33496b666831f2f-1555x1556.png', 'SUBUR SUPRIYADI', '6285890348976', '<p>Perguruan ini merupakan wadah pelestarian pencak silat yang memiliki basis massa kuat di wilayah Kabupaten Bogor. Saat ini, kepemimpinan perguruan dilanjutkan oleh Bapak Subur Supriyadi. Aktivitas pembinaan dan latihan perguruan ini tersebar di dua wilayah utama, yaitu:</p>
<p>Desa Petir, Kecamatan Dramaga, Kabupaten Bogor.</p>
<p>Desa Cinangka Tengah, Kecamatan Ciampea, Kabupaten Bogor.</p>', '<p>Perguruan ini didirikan secara resmi pada tanggal 8 Agustus 1980 di wilayah Desa Petir, Kecamatan Dramaga, Kabupaten Bogor. Tokoh sentral yang mendirikan sekaligus menjadi Guru Besar pertama adalah Almarhum Bapak M. Djakaria atau yang lebih akrab disapa dengan panggilan Abah Jako. Sejak berdiri hingga kini, perguruan tetap konsisten menjaga warisan tradisi silat dari sang pendiri untuk diteruskan kepada generasi muda di Bogor Barat.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('6LuKmvfZQ3bDFShaI1QXAF', 'GENDING JAGAD BUANA', 'gending-jagad-buana', 'SILAT NASIONAL', 150, 'KOTA DEPOK', '/uploads/perguruan-79bdb940dff44b9ffdb2077ae7c57dc525e3aa6b-1555x1556.png', 'DEDI SETIAWAN', '6281282448959', '<p>Gending Jagad Buana adalah perguruan bela diri asal Depok yang memadukan teknik kuncian, kecepatan gerak, dan olah pernapasan untuk meningkatkan energi serta stabilitas tubuh. Berlandaskan nilai kedisiplinan dan kejujuran, perguruan ini membina murid melalui sembilan tingkatan sistematis guna mencetak pribadi yang mampu mengendalikan diri dan menghormati sesama.</p>', '<p>Didirikan pada 19 Oktober 1995 oleh mendiang Rosah Lanarto, perguruan yang awalnya bernama Gending Semesta ini bertransformasi menjadi institusi profesional yang mengakar di Kota Depok. Perjalanan sejarahnya membawa misi filosofis sebagai "Irama Penakluk Dunia," di mana setiap murid diajarkan bahwa musuh sejati bukanlah orang lain, melainkan nafsu dalam diri sendiri.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('6LuKmvfZQ3bDFShaI1QXRL', 'GERAK PASEBAN', 'gerak-paseban', 'BETAWI', 35, 'DEPOK', '/uploads/perguruan-f080bb635599b2aff7a80f6188e80d77b019c59a-1555x1556.png', 'ELFRIDO', '6289688136275', '<p>Keluarga Pencak Silat (KPS) Gerak Paseban adalah perguruan silat yang saat ini aktif dikembangkan di wilayah Depok dan sekitarnya. Di bawah kepemimpinan penerusnya saat ini, yaitu Bang Elfrido (Bang Edo), perguruan ini sangat fokus pada pembinaan prestasi. Hal ini dibuktikan dengan keberhasilan KPS Gerak Paseban dalam mendidik banyak atlet yang telah berpartisipasi aktif dalam berbagai ajang pencak silat.</p>', '<p>Sesuai dengan namanya, akar sejarah dan asal-usul perguruan KPS Gerak Paseban bermula dari sebuah wilayah yang bernama Paseban di Jakarta. Perguruan ini didirikan dan dipimpin pertama kali oleh Guru Besar Alm. Engkong Salim bin Sinan. Sepeninggal beliau, amanah untuk menjaga dan menyebarkan keilmuan silat ini diteruskan oleh Bang Edo, yang sukses membawa perguruan ini terus berkembang hingga hari ini.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('6LuKmvfZQ3bDFShaI1QYPB', 'KONG RAHMAT', 'kong-rahmat', 'RAHMAT,SABENI', 50, 'CILANDAK', '/uploads/perguruan-f8e14bf5fb7234cd96a680d0fde6c92712370c78-1555x1556.png', 'ASRIL', '6285779671406', '<p>Perguruan Kong Rahmat merupakan wadah pelestarian seni bela diri tradisional yang secara konsisten melatih ketangkasan fisik dan karakter anggotanya. Dengan metode latihan yang disiplin, perguruan ini bertujuan membentuk generasi tangguh yang mampu mempertahankan diri sekaligus menjaga warisan budaya lokal.</p>', '<p>Aliran ini berakar kuat pada tradisi bela diri nusantara dengan membawa ciri khas gaya "Maen Pukul Tenabang" (Tanah Abang) yang melegenda. Perjalanan aliran ini merupakan bentuk nyata dedikasi para pendahulunya dalam menjaga orisinalitas gerakan silat Betawi di tengah perkembangan zaman.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('6LuKmvfZQ3bDFShaI1QYgH', 'MACAN BETAWI', 'macan-betawi', 'BETAWI', 30, 'KEMANG', '/uploads/perguruan-9f6bb3f986c3f79a29a9c0649d731d28dc40feca-1555x1556.png', 'KARNA', '6283878970583', '<p>Pencak Silat Macan Betawi Bogor merupakan perguruan yang berdedikasi membangun mental manusia yang beriman, berakhlak mulia, dan tangguh secara fisik. Saat ini, perguruan aktif membina 30 siswa melalui pendekatan latihan bela diri yang dikombinasikan dengan penguatan nilai-nilai spiritual.</p>', '<p>Berakar dari tradisi Si Pitung Rawa Belong yang diwariskan oleh Guru Besar Alm. Bapak Saidi, cabang Bogor ini didirikan pada 7 Agustus 1995 oleh Bapak Karma Wijaya Kusuma. Sempat mengalami masa vakum selama satu dekade, perguruan ini sukses bangkit kembali pada tahun 2016 untuk terus melestarikan ajaran silat di wilayah Bogor</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('6LuKmvfZQ3bDFShaI1Qb1b', 'SILEK HARIMAU', 'silek-harimau', 'SILAT NASIONAL', 100, 'DUREIN SAWIT', '/uploads/perguruan-c5a7a7d3ebc0243433589890c4f47b76e2ba69f8-1555x1556.png', 'EDWEL DATUAK RAJO GAMPO ALAM', '628129509711', '<p>Silek Harimau Minangkabau adalah warisan sistem pertahanan diri kultural yang memiliki akar sosiologis sangat dalam pada tata kehidupan masyarakat Persukuan Sikumbang, Balingka, Sumatera Barat. Keilmuan silat ini meniru dan mengadaptasi kelincahan, daya ledak kekuatan, sekaligus insting tajam sang harimau liar sebagai bentuk harmonisasi antara manusia dan alam semesta raya. Sebagai penjaga tradisi leluhur, penguasaan Silek Harimau menuntut kedisiplinan dan kesiapan mental tingkat tinggi karena terikat kuat dengan tata nilai adat, etika, dan spiritualitas Minangkabau. Pada abad modern ini, fungsionalitas mematikan Silek Harimau tidak lagi dieksklusifkan sekadar untuk pertahanan fisik murni antarkelompok. Alih-alih tertutup, beladiri legendaris ini telah bertransformasi rupa menjadi identitas peradaban luhur yang turut mengambil peran esensial dalam diplomasi budaya Minangkabau di tataran global.</p>', '<p>Jejak riwayat pewarisan Silek Harimau dapat dirunut silsilahnya jauh hingga penghujung abad ke-19 dari figur tetua adat Balingka, yaitu Enek Angguik. Kemurnian ilmu yang awalnya diproteksi dan hanya diajarkan di lingkaran persukuan tersebut dilestarikan oleh sang cucu, Enek Dina Sutan Mangkuto, sebagai pagar tradisi keluarga. Estafet utama mahakarya urang awak ini kemudian dipercayakan di pundak Edwel Datuk Rajo Gampo Alam, sosok pendekar yang dengan berani mengemas warisan ini melintasi batas-batas adat tradisional. Keputusan berani dan monumental Datuk Edwel pada 2006 untuk menembus sekat persukuan dan mengajarkannya ke masyarakat luas telah mendorong pesatnya kebesaran Silek Harimau. Kini, langkah revolusioner tersebut menjadikan gaya harimau nan buas tersebut dihormati di seantero negeri hingga dikagumi oleh seniman beladiri dari berbagai belahan dunia.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('6LuKmvfZQ3bDFShaI1QbRF', 'SINAR CIMANDE', 'sinar-cimande', 'CIMANDE', 50, 'KEMANG', '/uploads/perguruan-2d9fecba421f5c4569e0d76371d3a17ae0662388-1555x1556.png', 'NIMANG', '6281389743905', '<p>Perguruan Sinar Cimande hadir sebagai tonggak dan benteng pertahanan bagi keaslian teknik-teknik silat Cimande di seputaran wilayah Kemang, Kota Bogor. Lebih dari mencetak murid-murid yang ahli mengeksekusi rentetan pukulan mematikan, perguruan ini mendedikasikan waktu latihannya guna memahat karakter moral serta mengedukasi etika kearifan lokal kepada para penerus bangsa.</p>', '<p>Mulai disahkan kehadirannya pada kalender bersejarah tahun 1958, tampuk generasi pertama Sinar Cimande dikendalikan penuh oleh seorang figur sesepuh teladan, Abah Nimang. Menurunkan mandat luhur yang dititipkan oleh sang guru besarnya langsung, Abah Sata bin Muhasan, perguruan ini pun telah mapan merajut kebesaran dari sebuah rumah pembinaan di Kp. Sawah, Desa Bojong.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('6LuKmvfZQ3bDFShaI1Qc3i', 'TROTOK KIJANG PUTIH', 'trotok-kijang-putih', 'TROKTOK', 50, 'DEPOK', '/uploads/perguruan-fea7707015ac104de22fd1ea0ca6e4a7f826d2dc-1555x1556.png', 'AGUS SOPIAN', '6281221543990', '<p>Perguruan Silat Troktok Kijang Putih merupakan monumen hidup pelestari aliran kuno Bela Diri asli Betawi yang sangat dihormati eksistensinya dan berdiri menjulang dari batas batas Jakarta Selatan ke pedalaman Limo, Depok. Sesuai pakem filosofis label namanya yakni "Troktok", pesilat dari sanggar ini amat ditakuti kepiawaiannya menaklukkan pertahanan dengan gerakan memukul tiga kali runtut yang amat destruktif dan tajam bertenaga. Lewat identitas kebesaran pakaian tradisional berwarna kuning menyala, serangkaian anggota mudanya dididik intensif menyelami tidak hanya teknik pematahan fisik namun merasai nilai mahakarya luhur etika tradisi silat Betawi. Komunitas pemanen medali dan piala ini mencetak kekaguman masyarakat karena konsisten mempersembahkan pelatihannya sebagai pengabdian sosial tanpa harus memungut tarif iuran spesifik kepada setiap cantrik. Pencapaian ini mendefinisikan jati diri teguh para pendekarnya, bahwa mahkota nama besar Troktok Kijang Putih didedikasikan sepenuhnya hanya sebagai laskar pembela peradaban lokal nusantara.</p>', '<p>Susur galur sejarah tradisi silat hantam "tiga kali pukulan" ini sejatinya telah merekah wangi mengisi catatan kota pada medio 1940 asuhan telaten sesepuh karismatik Jakarta Selatan, Baba KH. Marzuki (Baba Majun). Selang berpuluh-puluh tahun pergantian estafet regenerasi pun berpindah di mana kepemimpinan pelatih diturunkan mulus tanpa gejolak ke pihak Baba Satar, kemudian Bapak Haji Yunus, serta diteruskan Bapak Haji Musa secara berurutan. Titik tonggak meresmikan diri sebagai sebuah wadah utuh formal baru meledak di tangan figur teladan mendiang Bang Aa kala mendirikan institusi "Troktok Kijang Putih" pada kurun tahun 1992 yang fenomenal. Menjajal peruntungannya berekspansi wilayah di era milenium, di bawah komando barunya lahirlah padepokan cabang sentral Limo Kota Depok kisaran 2013 yang amat sukses merekrut peminat. Keringat dan loyalitas trah pesilat generasi keempat bentukan asuhan Baba Majun ini klimaks merajai gelanggang kala menorehkan tintas emas menyabet mahkota bergengsi sebagai raihan Juara 2 Utama Se-Jabodetabek pada hajatan kalender kompetisi 2017.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('96443323-3fd4-4e17-b8a6-3997f17967b8', 'PUSAKA SABANDAR', 'pusaka-sabandar', 'SYABANDAR', 23, 'KABUPATEN BOGOR', '/uploads/perguruan-2a475dbb2e854347dc4a0b39a0ae44ee0c85a6ca-1555x1556.png', 'ABDUL MALIK SULAIMAN', '6283819368407', '<p><strong>Perguruan Pencak Silat Pusaka Sabandar</strong> mengajarkan integrasi antara olah gerak raga, teknik pernapasan khusus, dan meditasi (<em>tali rasa</em>). Ciri khas utamanya terletak pada setiap gerakan yang selalu diselaraskan dengan pengaturan napas. Metode ini tidak hanya bertujuan untuk bela diri dan keindahan seni, tetapi juga menghasilkan ketahanan fisik luar biasa (kekebalan terhadap benturan keras dan zat berbahaya) serta penyembuhan penyakit.</p>
<p>Saat ini, perguruan yang memiliki jurus andalan <strong>"Jurus Tangtung Alif"</strong> ini berpusat di <strong>Ciganjur, Jakarta Selatan</strong>, dengan sekitar 500 anggota yang tersebar di wilayah Cibubur, Guntur, Depok, Parung, hingga Mega Mendung.</p>', '<p>Perguruan ini memiliki rekam jejak transformasi kelembagaan yang jelas. Sebelumnya, perguruan ini dikenal dengan nama <strong>Perguruan Pencak Silat Gerak Raga Inkeda</strong>.</p>
<p>Perubahan identitas terjadi melalui musyawarah besar yang dihadiri oleh Dewan Guru, Dewan Pelatih, dan anggota di Jakarta pada tanggal <strong>4 April 1992</strong>. Kesepakatan tersebut menetapkan pergantian nama resmi menjadi <strong>Perguruan Pencak Silat Pusaka Sabandar</strong>, yang terus digunakan hingga saat ini dalam melestarikan warisan pencak silat berbasis tenaga dalam dan pernapasan.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('MCFZV9q1G62s454p8wTQbA', 'ASBD AL-AZHAR', 'asbd-al-azhar', 'SILAT NASIONAL', 150, 'TAPOS', '/uploads/perguruan-e8e69a4702df12aeb379593920d6e7b932c84c85-1555x1556.png', 'YUNIARSIH', '6285212678727', '<p>Perguruan silat ini merupakan wadah pembinaan seni bela diri yang terus melebarkan sayapnya ke berbagai wilayah. Untuk jangkauan wilayah Depok, perguruan ini memiliki pusat kegiatan dan kepengurusan dengan sekretariat resmi yang beralamat di Jl. Pekapuran No. 148, Tapos, Depok.</p>', '<p>Perguruan ini didirikan pertama kali pada tanggal 20 April 1970 oleh Guru Besar Kak M. Sugiono. Tempat lahirnya perguruan ini berada di lingkungan Masjid Agung Al Azhar, Jl. Sisingamangaraja, Jakarta Selatan.</p>
<p>Seiring perkembangannya, penyebaran ilmu bela diri ini meluas hingga ke Kota Depok. Cabang Depok resmi terbentuk pada tanggal 18 Agustus 2018 di Lapangan Gama Setu Golf, Tapos, atas inisiatif dan prakarsa tiga orang perintis, yaitu Yuniarsih, Karti, dan Elmiati.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('MCFZV9q1G62s454p8wTQqC', 'BEKSI MERAH DELIMA INDONESIA', 'beksi-merah-delima-indonesia', 'BEKSI', 100, 'JAKARTA SELATAN', '/uploads/perguruan-2b73a0d6aff464e4c4f1ccaaa3dbee2282f6a4e0-1555x1556.png', 'MUALI YAHYA', '6287884010108', '<p>Perguruan Beksi Merah Delima Indonesia (BMDI) adalah aliran seni bela diri asal Betawi yang bermarkas di Jagakarsa, Jakarta Selatan. Nama "BEKSI" bermakna pertahanan dari empat penjuru, sekaligus menjadi akronim filosofis "Berbaktilah Engkau Kepada Seruan Ilahi/Semua Insan".</p>
<p>Kekhasan utama BMDI terletak pada kecepatan dan kekuatan pukulan kepalan tangan terbalik. Sistem pelatihannya mencakup 12 jurus (seperti Beksi Dasar, Gedik, Tancep), 9 formasi, dan 6 kembangan yang dirangkai dalam prinsip rasa, reaksi, dan gerak. Selain olah fisik, BMDI sangat menekankan pembinaan moral dan spiritual melalui taushiyah rutin, agar para pesilat menjadi figur yang tangguh sekaligus membawa kedamaian bagi masyarakat. Saat ini, perguruan dipimpin oleh Ketua Umum Ali Sobirin dan Guru Tama Muali Yahya.</p>', '<p>Perkembangan BMDI tidak lepas dari peran penting pendirinya, yaitu Muali Yahya (akrab disapa Bang Ali), yang merupakan salah satu murid dari tokoh silat Beksi ternama, Babeh Nuh.</p>
<p>Di bawah kepemimpinan Bang Ali, BMDI mengalami kemajuan yang sangat pesat. Perguruan ini dikenal sangat inklusif dan aktif melebarkan sayap dengan menjalin silaturahmi antarsuku dan antarperguruan silat lainnya. Berkat dedikasi tersebut, BMDI kerap dilibatkan dalam berbagai kegiatan pertukaran seni dan budaya lintas provinsi di Indonesia.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('MCFZV9q1G62s454p8wTR5E', 'DANUR WENDAH', 'danur-wendah', 'SILAT NASIONAL', 150, 'DRAMAGA', '/uploads/perguruan-f9f3f9add9d26d9e5e841dbdb2eba184d525d6b7-1555x1556.png', 'TATANG SONJAYA', '6285889917459', '<p>Perguruan Silat Danur Wenda adalah lembaga bela diri yang membawa garis keilmuan aliran Cimande. Saat ini, pusat organisasinya berada di wilayah Sukabumi, namun eksistensinya tetap kuat dan mengakar di wilayah Bogor. Perguruan ini merupakan salah satu perguruan yang memiliki sejarah panjang, di mana hingga saat ini telah berdiri dan aktif melestarikan pencak silat selama 36 tahun.</p>', '<p>Perguruan Danur Wenda pertama kali didirikan di Bogor oleh tokoh Guru Besar, Alm. Abah Sanip. Sebagai bentuk regenerasi dan menjaga keberlangsungan ilmu, kepemimpinan dan sanad keilmuan perguruan kemudian diturunkan kepada Bapak Tatang. Di bawah bimbingannya, Danur Wenda terus berkembang dari akarnya di Bogor hingga memiliki pusat di Sukabumi, sambil tetap menjaga kemurnian teknik Cimande yang menjadi fondasi utamanya.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('MCFZV9q1G62s454p8wTRRm', 'GERAK SILAT PADJADJARAN', 'gerak-silat-padjadjaran', 'CIMANDE,SERA ULINMAKAO,MAENPO', 35, 'BOJONG GEDE', '/uploads/perguruan-2d3e7140c9deb413100f42221bde5c4e7b27bce7-1555x1556.png', 'MUHAMMAD RAHMAT RAMADHAN', '62896300605582', '<p>Perguruan Gerak Silat Padjajaran merupakan wadah pembinaan generasi muda yang berfokus pada penguasaan berbagai aliran pencak silat melalui latihan rutin dan ujian kenaikan tingkat setiap enam bulan. Selain memperdalam teknik bela diri, perguruan ini aktif berpartisipasi dalam berbagai kejuaraan untuk mengasah mental serta prestasi para anggotanya.</p>', '<p>Resmi dibentuk pada 23 November 2023 oleh Muhammad Rahmat Ramadhan, perguruan ini lahir dari semangat untuk melestarikan warisan budaya nusantara di kalangan kaum muda. Sejak awal pendiriannya, Gerak Silat Padjajaran berkomitmen menjadi institusi yang konsisten dalam mencetak praktisi silat yang tangguh dan berdedikasi.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('MCFZV9q1G62s454p8wTRoK', 'KI SAYAN', 'ki-sayan', 'BETAWI', 45, 'TAMBUN UTARA', '/uploads/perguruan-a71159ca81901cd4add7f6aa93c2462e8aed42f2-1555x1556.png', 'A.RAIS', '6285715416933', '<p>Perguruan Pencak Silat Ki Sayan merupakan lembaga bela diri tradisional di Tambun Utara, Bekasi, yang berdedikasi melestarikan kearifan lokal melalui pembinaan 30 anggota aktif. Di bawah kepemimpinan Bang Kamal, S.Pd.I, perguruan ini berfungsi sebagai sarana silaturahmi sekaligus penggerak seni budaya untuk memperkuat identitas nasional di tingkat daerah.</p>', '<p>Didirikan pada tahun 2015 di Desa Srijaya, Ki Sayan lahir dari semangat untuk menjaga keberlangsungan warisan leluhur agar tetap eksis di tengah perkembangan zaman. Sejak awal pembentukannya, perguruan ini berkomitmen menjadi pilar pelestari seni budaya di Kabupaten Bekasi melalui pendidikan karakter dan ketangkasan fisik bagi generasi muda.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('MCFZV9q1G62s454p8wTSAs', 'KIDANG KENCANA INDONESIA', 'kidang-kencana-indonesia', '-', 100, 'TANAH SAREAL', '/uploads/perguruan-906741f736ce4cbf6059bfe53927afe32896f45a-1555x1556.png', 'JUNAEDI', '6289637015893', '<p>Kidang Kencana Indonesia adalah perguruan pencak silat yang fokus pada pelestarian seni budaya sekaligus pengembangan prestasi para anggotanya. Melalui program latihan yang komprehensif, perguruan ini berkomitmen mencetak pesilat tangguh yang menjunjung tinggi warisan bela diri nusantara.</p>', '<p>Perguruan ini dibentuk berkat dedikasi empat tokoh pendiri, yakni Sutarma, Yayan Suryana, Hartanto, dan Junaedi. Visi awal mereka adalah menciptakan wadah yang tidak hanya menjaga tradisi pencak silat, tetapi juga mampu mengantarkan pesilatnya meraih prestasi gemilang di berbagai ajang.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('MCFZV9q1G62s454p8wTT90', 'PSHT', 'psht', 'CIMANDE,MINANG,SERA,SYABANDAR,CIKALONG', 220, 'CIBINONG', '/uploads/perguruan-27b5535c2109ff5edfdbfef5eed29716976c8ca9-1555x1556.png', 'HELLY SETIAWAN', '6285695860371', '<p>Persaudaraan Setia Hati Terate (PSHT) merupakan salah satu organisasi pencak silat paling ikonik di Indonesia yang menjunjung tinggi asas persaudaraan kekal antarsesama. Lebih dari sekadar mengajarkan teknik mematikan untuk pertahanan diri, PSHT mendidik warganya untuk memiliki keluhuran budi pekerti, mengetahui benar dan salah, serta bertaqwa kepada Tuhan Yang Maha Esa. Melalui latihan fisik dan penggemblengan spiritual (kerohanian), perguruan ini sukses mencetak individu yang tangguh, setia, dan berkarakter ksatria. Di era modern, PSHT semakin memperluas jangkauan kiprahnya melalui berbagai program pengabdian masyarakat yang memberikan dampak positif secara langsung. Dengan jutaan anggota yang tersebar di berbagai ranting, PSHT terus menjadi garda terdepan dalam menjaga keutuhan serta kelestarian budaya bangsa.</p>', '<p>Benih berdirinya PSHT mulai ditebar pada tahun 1922 di Madiun oleh Ki Hajar Hardjo Oetomo, seorang pahlawan Perintis Kemerdekaan Republik Indonesia. Pada masa awal pergerakannya, perguruan ini menggunakan nama Setia Hati Pemuda Sport Club (SH PSC) sebagai wadah perjuangan terselubung kaum muda untuk melawan penjajahan melalui jalur olahraga. Setelah melalui berbagai dinamika sejarah revolusi kemerdekaan, nama organisasi ini akhirnya diubah secara resmi menjadi "Persaudaraan Setia Hati Terate" bertepatan dengan kongres pertama di Madiun pada 25 Maret 1951. Seiring berjalannya waktu, struktur organisasi PSHT terus disempurnakan—termasuk pada periode DR. Ir. M. Taufiq SH., MSc—dengan menambah bidang pengabdian khusus kemasyarakatan. Hingga saat ini, akar kuat sejarah dari Madiun tersebut telah mekar menjadi perguruan pencak silat kelas dunia yang dihormati di mana-mana.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('MCFZV9q1G62s454p8wTTO2', 'PUSAKA PASUNDAN', 'pusaka-pasundan', 'CIMANDE', 100, 'LEUWILIANG', '/uploads/perguruan-2a475dbb2e854347dc4a0b39a0ae44ee0c85a6ca-1555x1556.png', 'HERYADI', '6289518124826', '<p>Perguruan Pencak Silat Pusaka Pasundan (Pusaka Sunda) adalah wadah pelestarian seni bela diri beraliran Cimande yang sangat kental dengan nuansa tradisi. Dikembangkan langsung oleh seorang seniman karawitan, perguruan ini tidak hanya berfokus pada ketangguhan fisik dan akurasi jurus, tetapi juga pada harmonisasi antara gerak silat dengan keindahan estetika budaya Sunda.</p>', '<p>Perguruan yang menjadikan Kp. Cibata, Desa Barengkok, Leuwiliang ini sebagai pusat latihannya resmi didirikan pada tanggal 13 Juli 2021. Sang pendiri, Heryadi (yang akrab disapa Abah Heri), memprakarsai berdirinya padepokan ini sebagai langkah dedikasi nyata untuk memastikan keaslian warisan maenpo Cimande tetap lestari di hati masyarakat modern.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('Vfx7hd7JwGrVL4MB8JDmh4', 'HAWA MURNI INDONESIA', 'hawa-murni-indonesia', 'SYABANDAR', 100, 'TAJURHALANG', '/uploads/perguruan-95c4fd806916b5cd7cf62e4eed452115789d8d0a-1555x1556.png', 'HIDAYAT', '6281295023910', '<p>PPS Hawa Murni Indonesia merupakan perguruan silat tradisi yang memadukan olah pernapasan dengan beragam aliran maenpo seperti Sabandar, Cimande, hingga Cikalong. Berpusat di Tajurhalang, Kabupaten Bogor, perguruan ini aktif menyeimbangkan pelestarian budaya leluhur dengan pengembangan atlet pada cabang pencak silat olahraga prestasi.</p>', '<p>Didirikan pada tahun 1970-an oleh almarhum Abah Udin Syamsudin dengan nama awal Sport Gerak Hawa Murni, perguruan ini merintis langkah pertamanya di kawasan Cidodol, Jakarta Selatan. Saat ini, tongkat estafet kepemimpinan dilanjutkan oleh Babe Hidayat sebagai pewaris Guru Besar bersama Kang Yatna sebagai Ketua Umum guna terus mengembangkan syiar perguruan.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('Vfx7hd7JwGrVL4MB8JDnLs', 'KATEDA PTI', 'kateda-pti', 'SYABANDAR', 150, 'TANAH SAREAL', '/uploads/perguruan-d462fee53a7dda7db6b848e90429882feb9c5613-1555x1556.png', 'R. JOKO SARJANOKO', '628129511993', '<p>Beladiri PTI (KATEDA) adalah organisasi bela diri dinamis yang berfokus pada pengembangan kualitas manusia seutuhnya melalui prinsip keterbukaan dan inklusivitas tanpa diskriminasi. Di bawah naungan IPSI, perguruan ini mengajarkan teknik pertahanan diri yang akomodatif terhadap perubahan zaman dengan tetap mengedepankan nilai-nilai persaudaraan untuk membentuk karakter yang kuat.</p>', '<p>Kehadiran KATEDA di Indonesia menandai terpecahkannya rahasia besar ilmu bela diri yang berakar dari penemuan manuskrip asli di Pegunungan Himalaya. Sejarahnya didedikasikan untuk menghidupkan kembali ilmu yang sempat terlupakan guna menciptakan perdamaian dunia, di mana kekuatan fisik digunakan semata-mata untuk melawan unsur yang menghalangi ketenangan hidup umat manusia.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('Vfx7hd7JwGrVL4MB8JDnTI', 'KHOMSATUN NUFUS', 'khomsatun-nufus', 'SYABANDAR', 80, 'PANCORAN MAS', '/uploads/perguruan-31f90a0259c5651c8496ff8cc7d04911d8d82ca1-1555x1556.png', 'ADI PRAYOGA', '6282125729505', '<p>Khomsatun Nufus merupakan wadah pembinaan karakter dan bela diri yang terintegrasi secara langsung dengan lingkungan pendidikan keagamaan. Dengan memfokuskan seluruh kegiatannya pada pembekalan fisik dan spiritual, lembaga ini terus berdedikasi untuk mencetak generasi santri yatim yang tangguh, mandiri, serta berakhlak mulia.</p>', '<p>Perjalanan Khomsatun Nufus bermula dari sebuah inisiatif mulia yang lahir di dalam lingkungan Pondok Pesantren Binaatufiq Atap Yatim. Sejak titik awal pendiriannya hingga saat ini, seluruh denyut nadi kegiatan dan pengembangannya tetap setia bernaung di pesantren tersebut sebagai wujud pengabdian yang tak terputus.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('Vfx7hd7JwGrVL4MB8JDoOn', 'SIN LAM BA', 'sin-lam-ba', 'SYABANDAR', 150, 'JAKARTA PUSAT', '/uploads/perguruan-285e96f50f7414b9e4dcf31c0542e3200ab55462-1555x1556.png', 'DZUMAIL', '6287784555134', '<p>Perguruan Silat Sin Lam Ba (Sinlamba) adalah salah satu tonggak orisinal maen pukul asli Betawi yang sangat difavoritkan berkat kepraktisan teknik pertarungan jarak dekatnya yang amat mematikan. Di samping memfokuskan porsi latihannya pada insting refleks pembelaan diri tingkat tinggi, aliran ini menanamkan kedisiplinan serta akhlak religius yang menjadi DNA tak terpisahkan dari seorang pendekar Betawi sejati.</p>', '<p>Aliran yang kental nilai religius ini pertama kali diciptakan dan dikenalkan oleh guru besar mumpuni, Bapak Toha bin Sieng, kepada lingkar masyarakat Betawi. Amanat menjaga silsilah dan perbendaharaan keilmuannya dilanjutkan secara tulus oleh Harun bin Achmad, dan kini terus bergulir menempa masa depan generasi muda di bawah pengawasan sosok tangguh Bapak Djumail.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('ZyC1rDVv23cf5YRFt9L72R', 'CINGKRIK GONING TB BAMBANG', 'cingkrik-goning-tb-bambang', 'CINGKRIK', 50, 'GEROGOL PETAMBURAN', '/uploads/perguruan-281e7f1a3926fcc7f6752ca10178e36278fadaaf-1555x1556.png', 'TB. BAMBANG', '628170151509', '<p>Silat Cingkrik Goning adalah salah satu aliran seni bela diri tradisional asli Betawi yang sangat termasyhur dan telah berusia ratusan tahun. Berbasis di daerah Kedoya, aliran ini memiliki karakteristik yang sangat khas, yaitu gerakan jurus yang panjang dan lebar—berbeda dengan aliran Cingkrik Sinan yang identik dengan gerakan pendek.</p>
<p>Saat ini, kelestarian keilmuan Cingkrik Goning terus dijaga oleh para generasi penerusnya, mulai dari murid utamanya yaitu Babe Usup Utai hingga tokoh-tokoh masa kini seperti TB. Bambang Sudrajat.</p>', '<p>Nama aliran ini diambil dari tokoh legendarisnya, yaitu Kong Goning (nama asli: Ainin Bin Urim, 1895–1975). Panggilan "Goning" berasal dari nama panggilannya "Nin" atau "Ning", yang kemudian ditambah ledekan khas Betawi "Go" di depannya.</p>
<p>Kong Goning dikenal sebagai seorang pejuang yang sering melakukan perjalanan berhari-hari ke daerah Marunda (wilayah kekuasaan Ki Pitung). Ilmu silatnya yang tangguh kemudian diwariskan kepada keempat anak laki-lakinya (Kosim, H. Husien, H. Sa''adih, dan Hasan Jago) serta murid andalannya, Babe Usup Utai (1927–1993), yang memastikan aliran Cingkrik Goning tetap hidup melintasi zaman.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('ZyC1rDVv23cf5YRFt9L7LJ', 'GARUDA  PUTIH', 'garuda-putih', 'CIMANDE', 85, 'BOJONG GEDE', '/uploads/perguruan-12c9e1b70cf925c0066263c13f7893ed4518d1ee-1555x1556.png', 'AGUS SISWANTO', '6287705552340', '<p>Berdiri sejak 2015, klub ini merupakan pusat pengembangan karakter dan pembinaan prestasi yang berdedikasi mencetak generasi unggul di bidang olahraga. Melalui pendekatan yang disiplin, kami berkomitmen melahirkan individu yang tidak hanya tangguh secara fisik, tetapi juga memiliki mentalitas juara.</p>', '<p>Sejak awal pendiriannya, klub ini telah menorehkan jejak gemilang dengan berhasil mencetak atlet-atlet kompetitif untuk ajang PORDA, POPWILDA, hingga O2SN. Kontribusi aktif dalam berbagai kejuaraan tingkat regional maupun nasional menjadi bukti konsistensi kami dalam memajukan prestasi olahraga di Indonesia.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('ZyC1rDVv23cf5YRFt9L7Zz', 'GERAK SAKA', 'gerak-saka', 'GERAK SAKA', 30, 'BOJONG GEDE', '/uploads/perguruan-cc39b1901f85ca2a13ae16859f8ebb32ddbb32d1-1555x1556.png', 'NUSMI KADZATUPAMA SIWI', '6287870090082', '<p>Perguruan Pencak Silat Gerak Saka berfungsi sebagai sarana silaturahmi, olahraga, dan pendidikan sosial yang berfokus pada kaderisasi serta kekaryaan generasi muda. Melalui pengembangan potensi fisik dan mental, perguruan ini berkomitmen menjadi wadah komunikasi yang produktif bagi para anggotanya.</p>', '<p>Aliran silat ini berakar dari tradisi keluarga bangsawan (menak) Sunda Prabu Siliwangi yang diwariskan oleh Raden Widarma kepada Raden H. Muhammad Sjafe''i R. (1931–2001). Sebagai tokoh kunci, Raden Muhammad Sjafe''i kemudian menjadi cikal bakal sekaligus pendiri yang meresmikan berdirinya Perguruan Gerak Saka.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('ZyC1rDVv23cf5YRFt9L7mZ', 'KOTEK PARUNG INDONESIA', 'kotek-parung-indonesia', 'KOTEK LANGKAH 7 , BETAWI', 55, 'PARUNG', '/uploads/perguruan-45f1fae31c708a9489a989ec35a56b4f30242553-1555x1556.png', 'ROMELIH', '6289646662726', '<p>PPS Kotek Parung Indonesia adalah perguruan bela diri yang gigih melestarikan seni maen pukul khas daerah Parung melalui teknik andalannya, "Mainan Takep Ujung". Perguruan ini secara aktif membina kelincahan fisik dan mental anggotanya agar selaras dengan nilai-nilai tradisional yang luhur.</p>', '<p>Beraliran "Langkah Tujuh Parung", perguruan ini mewarisi ilmu beladiri langsung dari tokoh utamanya, Kong Naba bin H. Ribin. Saat ini, tradisi dan kemurnian teknik tersebut terus dijaga serta diteruskan di bawah bimbingan dewan guru Bin Nani Naba agar tidak lekang oleh waktu.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('ZyC1rDVv23cf5YRFt9L87X', 'PERISAIDIRI', 'perisaidiri', 'SILAT NASIONAL', 100, 'JAKARTA SELATAN', '/uploads/perguruan-a07a9b23b702c367b9c13d7156a9291a0cab5158-1555x1556.png', 'ARI WINARKO', '6289697520752', '<p>Keluarga Silat Nasional Indonesia Perisai Diri (Kelatnas Indonesia Perisai Diri) adalah perguruan bela diri historis yang menyajikan keunikan teknik perpaduan antara silat Nusantara dan Kungfu Shaolin. Perguruan ini mengajarkan sistem pertahanan diri yang sangat efektif dan terstruktur, dengan mengambil inti sari dari sekitar 156 aliran silat daerah di Indonesia serta elemen beladiri Tiongkok. Selain fokus pada ketangkasan fisik, Perisai Diri menaruh perhatian besar pada pendidikan karakter, kedisiplinan, dan sikap mawas diri para anggotanya. Diakui sebagai salah satu perguruan terbesar di bawah naungan IPSI, kurikulumnya kini diajarkan secara luas mulai dari tingkat sekolah dasar hingga perguruan tinggi. Melalui metode yang aman, cerdas, dan sistematis, Perisai Diri terus berkomitmen mencetak pesilat tangguh berkaliber internasional.</p>', '<p>Sejarah Perisai Diri bermula dari figur R.M. Soebandiman Dirdjoatmodjo (Pak Dirdjo), seorang bangsawan keraton Yogyakarta yang telah merantau untuk mempelajari berbagai ilmu bela diri sejak usia muda. Berkat saran dari tokoh pendidikan Ki Hajar Dewantara, Pak Dirdjo awalnya mulai mengajar silat di lingkungan Taman Siswa, Wirogunan, Yogyakarta. Puncaknya, pada 2 Juli 1955, beliau secara resmi mendirikan Kelatnas Indonesia Perisai Diri di kota Surabaya, Jawa Timur. Menjelang akhir hayatnya pada tahun 1982, Pak Dirdjo mengangkat 23 murid terbaiknya sebagai Pendekar Historis untuk meneruskan estafet kepemimpinan perguruan. Kini, warisan luhur Pak Dirdjo tidak hanya lestari di tanah air, tetapi telah melebarkan sayapnya hingga mendunia ke Eropa, Amerika, dan benua Australia.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('ZyC1rDVv23cf5YRFt9L8Wh', 'SELENDANG POKSAY', 'selendang-poksay', 'JALAN ENAM', 75, 'BOJONGSARI', '/uploads/perguruan-23704fa21cad1dcc0c930d640be5efedbd0858e1-1555x1556.png', 'SUDIRMAN', '628990810612', '<p>Perguruan Silat Selendang Poksay merupakan padepokan bela diri tradisional yang mengedepankan taktik pertarungan murni lewat gabungan dua aliran silat Betawi legendaris: Jalan Enam dan Beksi. Perpaduan sempurna ini menciptakan sistem pertahanan diri yang memadukan kokohnya pijakan kuda-kuda dengan rentetan pukulan rapat dan tangkisan yang sangat sulit ditembus oleh lawan.</p>', '<p>Kehadiran Selendang Poksay dalam peta persilatan Nusantara menjadi saksi bisu dari upaya gigih merawat tradisi maen pukul yang diwariskan lintas generasi di kampung-kampung Betawi. Dengan setia memelihara teknik orisinal Jalan Enam dan kebrutalan terukur dari Beksi, perguruan ini hadir agar nilai-nilai kejantanan serta kesantunan tradisi asli tetap hidup berdampingan.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('ab7c58d1-0267-4976-b559-45740c03bf30', 'THIFAN PO KHAN', 'thifan-po-khan', 'THIFAN', 100, 'KABUPATEN BOGOR', '/uploads/perguruan-a9d9da8fd590c64a89e67690a75a970278fee6fb-1555x1556.png', 'HERMAN BUDIANTO', '6281316106633', '<p><strong>Syurulkhan Nie Thifan Po Khan</strong> (berarti "Siasat Bangsawan Turfan") adalah seni beladiri yang memadukan teknik <em>Shaolin Kungfu</em> dengan ragam beladiri Asia Tengah (Mogul, Tartar, Wigu) yang telah diselaraskan dengan ajaran Islam. Sistem pelatihannya menyeimbangkan aspek fisik, akal, dan rohani.</p>
<p>Materi latihan mencakup teknik keras (pukulan, tendangan, senjata) hingga teknik lembut (pengobatan dan totok). Beladiri ini memiliki jenjang pendidikan ketat yang terdiri dari 12 tingkatan (7 tingkat Tamid/murid dan 5 tingkat Badur/pendekar) yang membutuhkan waktu puluhan tahun untuk diselesaikan. Saat ini, kemurnian ajarannya dijaga di bawah naungan <strong>Persaudaraan Thifan Po Khan Indonesia (PTI)</strong> sebagai ilmu wakaf yang harus diajarkan secara tuntas.</p>', '<p>Akar sejarah Thifan bermula sekitar tahun <strong>1100 M</strong> di Turkistan Timur, saat seorang ustadz muda bernama <strong>Je''nan</strong> berguru kepada pendekar <strong>Badur Namsuit</strong>. Ilmu ini kemudian menyebar luas, bahkan tercatat dikuasai oleh keluarga Sultan Shalahuddin Al Ayyubi di Mesir dan menjadi bekal prajurit Turki Utsmani.</p>
<p>Thifan masuk ke Indonesia melalui Aceh pada tahun <strong>1678</strong> bersama bantuan pasukan Turki Utsmani, lalu menyebar ke Jawa pada tahun 1900-an. Di era modern (tahun 1970-an), ilmu ini dikembangkan di Jakarta oleh <strong>Ust. AD El Marzdedeq</strong>, satu-satunya pewaris yang tercatat memiliki kemampuan setara para Badur terdahulu. Sepeninggal beliau pada 2013, pelestarian Thifan dilanjutkan oleh murid-murid seniornya untuk menjaga keaslian ajaran sesuai <em>Kitab Zho Dam</em>.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('bea44a07-4959-4acf-baa8-2db704aa2110', 'SERA BONGKAR KANDANG', 'sera-bongkar-kandang', 'SERA', 85, 'KABUPATEN BOGOR', '/uploads/perguruan-16a7360641e4c1f7cd42aa541d7d1648754e5899-1555x1556.png', 'ALM. ADE SOPIAN', '6287783821285', '<p><strong>Perguruan Silat Wonga Tua Kaulinan Sera Bongkar Kandang</strong> adalah aliran silat tradisional yang berakar kuat di wilayah Bogor. Saat ini, perguruan dipimpin oleh Guru Besar <strong>Abah Ade Sopian</strong>, yang merupakan pewaris langsung garis keturunan pendiri.</p>
<p>Sejak pembukaan kembali unit latihan secara terbuka pada tahun 2014 di Jampang Pulo, Kemang, perguruan ini mengalami perkembangan pesat. Dari segelintir murid, kini perguruan telah memiliki banyak anggota aktif dan terus melebarkan sayap dengan membuka berbagai unit latihan di wilayah Kabupaten dan Kota Bogor, didukung oleh tim asisten pelatih yang solid.</p>', '<p>Sejarah perguruan bermula dari perjuangan melawan penjajah Belanda dan Jepang yang dilakukan oleh <strong>Abah S. Anda</strong> (lahir 1911) bersama ayahnya, <strong>Abah Anin</strong>. Demi memperdalam ilmu untuk melawan penjajah, Abah S. Anda berguru ke Banten kepada ayah angkatnya, <strong>Abah Godok (Raden Papak)</strong>.</p>
<p>Setelah masa perjuangan, Abah Godok berkunjung ke Bogor dan melakukan uji tanding persahabatan dengan Abah Anin. Karena ilmu keduanya terbukti sama kuat, mereka sepakat mendirikan <strong>Perguruan Silat Sera</strong> pada tahun <strong>1946</strong> di Cibuluh, Bogor.</p>
<p>Kepemimpinan perguruan berjalan turun-temurun, mulai dari Abah Anin, dilanjutkan oleh Abah S. Anda, hingga akhirnya diwariskan kepada cucunya, <strong>Abah Ade Sopian</strong>. Abah Ade telah digembleng sejak usia 7 tahun untuk menjadi penerus, dan resmi memimpin perguruan setelah wafatnya Abah S. Anda pada tahun 1991.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('c64d76c4-5ca2-4db7-b334-9ed59523c1ac', 'SALAKA MACAN PUTIH', 'salaka-macan-putih', 'CIMANDE', 50, 'KABUPATEN BOGOR', '/uploads/perguruan-2312eda8a29bf65dfe02184339bbd94812c42464-1555x1556.png', 'EDI NURDIANA', '6281808101666', '<p><strong>PS. SALAKA MACAN PUTIH</strong> adalah perguruan pencak silat yang aktif mendedikasikan diri dalam pelestarian seni budaya, menyeimbangkan antara aspek tradisi dan prestasi olahraga. Perguruan ini memiliki basis latihan yang kuat dan beragam, mencakup latihan rutin di lingkungan masyarakat, kegiatan ekstrakurikuler di sekolah-sekolah, hingga pembinaan santri di pondok pesantren</p>', '<p>Perguruan ini didirikan pada tahun <strong>2012</strong> oleh tokoh pendirinya, <strong>Abah Edi Nurdiana</strong>. Dalam perjalanan perkembangannya untuk memperluas syiar dan jaringan silat, PS. SALAKA MACAN PUTIH resmi bergabung dengan <strong>KSJ</strong> pada tahun <strong>2015</strong>. Sinergi ini terus terjalin hingga saat ini dalam upaya mengembangkan pencak silat di wilayahnya.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('ca1bcddf-141e-4c15-ab3b-f1bd91d5b2bb', 'SATRIA MUDA INDONESIA', 'satria-muda-indonesia', 'SYABANDAR, SERA, CIMANDE', 150, 'KABUPATEN BOGOR', '/uploads/perguruan-fe58669ad5ef4ef74cd7d2dacaec13363fb6c73e-1555x1556.png', 'SAPTDAJI', '6285773354876', '<p><strong>Perguruan Pencak Silat Satria Muda Indonesia (PPS SMI)</strong> adalah organisasi pencak silat besar yang memiliki jaringan luas, mulai dari seluruh pelosok Indonesia hingga ke mancanegara. Sebagai wadah pembinaan karakter generasi muda, perguruan ini aktif membuka unit latihan di berbagai daerah, salah satunya yang cukup aktif berada di kawasan <strong>Kampung Silat Jampang, Kabupaten Bogor</strong>.</p>', '<p>PPS SMI didirikan secara resmi pada tanggal <strong>19 Juli 1987</strong> di <strong>Lembah Pinus, Ciloto, Bogor, Jawa Barat</strong>. Tokoh utama pendiri perguruan ini adalah Bapak <strong>Prabowo Subianto</strong>. Sejak awal pendiriannya, perguruan ini didedikasikan untuk melestarikan pencak silat sebagai budaya bangsa sekaligus sarana pembentukan mental dan fisik para satria muda.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('dara1f7ycl7loM6gieDQCI', 'CIMANDE BINTANG LIMA', 'cimande-bintang-lima', 'CIMANDE', 50, 'TANAH ABANG', '/uploads/perguruan-526093657fba1d6d2367ae9edce6590d97daedeb-1555x1556.png', 'TANTRI NOOR', '6285767054446', '<p>Perguruan Cimande Bintang Lima adalah wadah pelestarian pencak silat yang saat ini aktif melakukan pembinaan masyarakat melalui kegiatan latihan rutin di RPTRA Sunter Agung, serta menjadi ekstrakurikuler di berbagai sekolah. Nama "Bintang Lima" diambil dari landasan filosofis perguruan yang sarat makna spiritual dan nasionalis, yaitu melambangkan Rukun Islam, Sahabat Nabi, dan Pancasila.</p>', '<p>Berdirinya perguruan ini berawal dari perkumpulan sekelompok remaja yang antusias belajar silat Cimande di bawah bimbingan Abah Syam, seorang guru yang mewarisi aliran Macan Betawi, Gagak Lumayung, dan Cimande. Langkah perkumpulan ini semakin mantap setelah mereka melakukan silaturahmi ke Pusat Budaya Cimande di Talang 2. Kunjungan tersebut menjadi momen penting yang akhirnya menginisiasi pembentukan resmi Perguruan Cimande Bintang Lima.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('dara1f7ycl7loM6gieDRt8', 'GERAK PANCA', 'gerak-panca', 'BETAWI LANGKAH LIMA', 150, 'BOJONG GEDE', '/uploads/perguruan-b24bcd619e490fceb2f1cba5a86e939b11b1cab5-1555x1556.png', 'M BURHAN', '6285715666671', '<p>Perguruan Seni Maen Pukul Gerak Panca merupakan pusat pelestarian tradisi bela diri aliran Maen Pukulan Betawi yang berlokasi di Bojonggede, Kabupaten Bogor. Di bawah bimbingan langsung M. Burhan selaku pendiri, perguruan ini berfokus pada pengembangan ketangkasan fisik dan pelestarian budaya lokal bagi masyarakat sekitar.</p>', '<p>Cikal bakal Gerak Panca mulai dikembangkan secara aktif sejak awal tahun 2021 untuk memperkenalkan kekayaan seni pukul Betawi di wilayah Bogor. Momentum perjalanannya ditandai dengan peresmian secara formal pada tanggal 21 Mei 2021, yang menjadi tonggak awal kiprahnya dalam mencetak praktisi bela diri tradisional yang tangguh.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('dara1f7ycl7loM6gieDSOa', 'IKS KERA SAKTI', 'iks-kera-sakti', 'IKS, KUNTAUW', 100, 'CITEURUP', '/uploads/perguruan-206336809082dc37a4acd3015c946cdda431dcf6-1555x1556.png', 'YUYUN HARUN ALRASYAD', '6282299379076', '<p>IKS.PI Kera Sakti adalah perguruan bela diri unik yang memadukan ketangkasan Kung Fu Tiongkok aliran Nan Pie Ho Jien dengan teknik Pencak Silat Indonesia. Berfokus pada keseimbangan antara kekuatan fisik dan kerohanian, perguruan ini membina muridnya menjadi pribadi tangguh yang menjunjung tinggi persaudaraan di bawah naungan falsafah kesetiaan yang tak terpatahkan.</p>', '<p>Didirikan oleh Raden Totong Kiemdarto pada 15 Januari 1980 di Madiun, perguruan ini lahir dari semangat untuk memperkenalkan seni bela diri yang awalnya eksklusif kepada masyarakat umum. Dari basisnya di Jawa Timur, IKS.PI Kera Sakti telah berkembang pesat hingga ke mancanegara, membawa identitas khas "Jurus Kera" serta motto keberanian untuk pantang tunduk kepada musuh.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('dara1f7ycl7loM6gieDSjY', 'KAULINAN PETANI', 'kaulinan-petani', 'JALAN ENAM', 35, 'BOJONGSARI', '/uploads/perguruan-167f54822d8a9fec19d6426262cccfba08fe2f12-1555x1556.png', 'TATANG SUHANA', '6281908909006', '<p>Perguruan ini merupakan wadah pelestarian seni Maen Pukul tradisional yang memadukan latihan fisik dengan kegiatan spiritual melalui pengajian rutin dan aksi sosial kemasyarakatan. Selain fokus pada penguatan bela diri, perguruan ini juga aktif menghidupkan tradisi budaya seperti seni Gendang Pencak dan prosesi Palang Pintu.</p>', '<p>Berdiri sejak tahun 1970, aliran ini berakar dari tradisi "Silat Jalan Enam Kotek" yang pada mulanya dikembangkan dan dimiliki secara turun-temurun oleh kalangan petani. Sejarah panjangnya mencerminkan ketangguhan masyarakat agraris dalam menjaga pertahanan diri sekaligus mempertahankan nilai-nilai luhur nusantara hingga saat ini.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('dara1f7ycl7loM6gieDTkS', 'SAKELID SIMA MAUNG', 'sakelid-sima-maung', 'CIMANDE', 60, 'BOJONG GEDE', '/uploads/perguruan-dac73474294ad47ce6d30305e7d703790b1d75aa-1555x1556.png', 'MUHAMMAD SOPYAN SAURI', '6281382251123', '<p>Sakelid Sima Maung merupakan lembaga pengembangan silat aliran Cimande yang unik karena mengusung konsep keorganisasian progresif di tengah balutan tradisi klasik. Perguruan ini secara cerdas memadukan nilai-nilai orisinalitas bela diri dengan sistem administrasi, manajemen keorganisasian, serta kurikulum tingkatan sabuk yang modern.</p>', '<p>Lahir dari upaya menjawab tantangan zaman tanpa merusak keluhuran warisan leluhur, Sakelid Sima Maung berdiri sebagai jembatan antara masa lalu dan era masa kini. Melalui modifikasi metode pelatihannya yang selalu up-to-date, perguruan ini sukses membuktikan bahwa ajaran bela diri klasik yang antik dapat terus bertahan secara profesional sebagai gaya hidup pelindung diri.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('dara1f7ycl7loM6gieDUVd', 'SILIH KELID', 'silih-kelid', 'CIMANDE', 70, 'DRAMAGA', '/uploads/perguruan-aa2bfef2a6f43435693b3a152574e9b8ef07f5d5-1555x1556.png', 'UNAY', '6285887512194', '<p>Perguruan Silat Silih Kelid merupakan komunitas padepokan pelestari keilmuan Cimande yang menitikberatkan penguasaan teknik kelid (tangkisan atau elakan refleks) sebagai kunci pertahanan mutlak di garis depan. Menyaring inti sari dari kekuatan dan kelembutan ajaran maenpo Jawa Barat, tempat ini gigih menggembleng psikis dan disiplin para pesilat dengan metode latihan tradisional yang autentik.</p>', '<p>Membawa keabsahan jalur sanad dari pimpinan Guru Besar yang mengakar kuat di dataran Sukabumi, Silih Kelid memperluas jangkar silaturahminya dengan berlabuh tegak di bumi Bogor. Memasuki usianya yang keempat tahun dalam membina cabang di kota hujan, perguruan ini gigih mencetak atlet yang santun dengan karakter petarung tangguh guna membentengi warisan nenek moyang dari gerusan budaya modern.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('dara1f7ycl7loM6gieDUqb', 'SIUNG MAUNG SILAT CIMANDE', 'siung-maung-silat-cimande', 'CIMANDE', 50, 'BOJONG GEDE', '/uploads/perguruan-af8c572f2dfdd3008adcaae5aa9971dbea222201-1555x1556.png', 'SUHERMAN', '6283173300257', '<p>Perguruan Sihung Maung Silat Cimande mendobrak kebiasaan lama dengan cara membawa ajaran beladiri tradisional progresif masuk merapat ke lingkungan ranah pendidikan sekolah. Dengan menggabungkan porsi kedisiplinan pelatihan fisik dan pendidikan budi pekerti yang kuat, wadah persilatan ini melebarkan pesonanya secara masif melalui jalur ekstrakurikuler pelajar di usia sangat krusial.</p>', '<p>Meski umurnya baru merangkak menapaki lima tahun kelahirannya sejak 2020 silam, manuver sanggar ini dalam mencetak kader atlet pemula membuahkan hasil luar biasa di seantero area Bojonggede. Konsistensi tersebut ditandai tegas lewat pembentukan unit aktif di wilayah Bilabong yang memanjang sampai di lingkungan SMP Tonjong, SMP Asy-Syarifiyyah, SMP PGRI, hingga lingkup pelajar dasar di SDN Bojonggede 03.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('f3X7DbHwye8dXmEJTn4aMD', 'LODAYA KEMUNING', 'lodaya-kemuning', 'CIMANDE', 50, 'BOJONG GEDE', '/uploads/perguruan-40fcff42d482d8252deefa6f2627d65b4618ed45-1555x1556.png', 'WANG WARTONO', '6285814288127', '<p>Perguruan Lodaya Kemuning adalah institusi bela diri di Bojonggede yang memfasilitasi pembinaan karakter dan fisik untuk berbagai kalangan usia. Latihan rutin diselenggarakan secara terstruktur, yakni pada Sabtu malam untuk anggota dewasa dan Minggu pagi untuk kelas anak-anak, guna memastikan pewarisan ilmu yang berkelanjutan.</p>', '<p>Perguruan ini memiliki akar sejarah yang kuat dari salah satu perguruan pusat yang bergengsi di Kota Bogor. Sang pendiri kemudian melakukan hijrah ke kawasan Bojonggede dan mendirikan Lodaya Kemuning sebagai langkah proaktif untuk menyebarkan serta mengembangkan seni bela diri di wilayah yang baru.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('f3X7DbHwye8dXmEJTn4aZl', 'MAWAR PUTIH INDONESIA', 'mawar-putih-indonesia', 'BETAWI,SUNDA', 80, 'SAWANGAN DEPOK', '/uploads/perguruan-b977f28c6b264f053c23844d4f660afbad87e3e5-1555x1556.png', 'ILHAMSYAH', '6285711764631', '<p>Perguruan Silat Seraput Mawar Putih Indonesia merupakan entitas bela diri dinamis yang dengan apik meramu karakteristik silat Betawi dan Sunda ke dalam satu kesatuan jurus. Peleburan dua identitas aliran kultural ini tak sekadar menghasilkan serangkaian teknik perlindungan diri yang kuat, tetapi turut melahirkan kekayaan seni pergerakan badan yang begitu elok dipandang.</p>', '<p>Diikrarkan pendiriannya tepat pada tanggal 19 April 2008, perguruan ini dilahirkan sebagai manifestasi wujud dedikasi untuk menjembatani pelestarian dua khazanah kebudayaan besar di Indonesia. Seiring bergulirnya waktu, Seraput Mawar Putih terus memelihara warisan filosofi silat legendaris tersebut agar dapat senantiasa diwarisi oleh generasi-generasi muda bangsa secara berkelanjutan.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('f3X7DbHwye8dXmEJTn4bEP', 'MUSTIKA SILIWANGI', 'mustika-siliwangi', 'SYABANDAR', 50, 'TAPOS', '/uploads/perguruan-c0bb94d49bb38bfaef06477ebeaf487f63cd40b6-1555x1556.png', 'SUKARDI', '628588224295', '<p>Sanggar Mustika Siliwangi merupakan sebuah wadah edukasi pelestarian kesenian dan budaya Nusantara yang terpusat di kawasan Tapos, Kota Depok. Sanggar ini tidak hanya membina pencak silat, melainkan juga menaungi beragam bentuk seni tradisional seperti gambang kromong, degung, ondel-ondel, marawis, hingga rampak bedug sebagai media pembentukan karakter pemuda.</p>', '<p>Keberadaan Mustika Siliwangi mulai semakin solid setelah mendapat dukungan resmi berupa bantuan pembangunan padepokan seni dari Pemerintah Provinsi Jawa Barat pada tahun 2010. Sejak saat itu, Mustika Siliwangi menjadi salah satu episentrum pergerakan seniman di Kota Depok untuk menjaga warisan seni silat dan kesenian Betawi-Sunda agar tetap eksis melintasi zaman.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('f3X7DbHwye8dXmEJTn4bRx', 'PADJADJARAN CIMANDE', 'padjadjaran-cimande', 'CIMANDE', 150, 'PANCORAN MAS', '/uploads/perguruan-716079bd5bcadcdbfc66a52e819f6423bd1fb4ff-1555x1556.png', 'YUSUF SARWO EDI', '6287899741000', '<p>Keluarga Besar Padjadjaran Cimande (KBPC) adalah salah satu organisasi pencak silat terbesar yang mewarisi kekayaan teknik pertahanan diri beraliran murni Cimande. Perguruan ini mengajarkan sistem bela diri lengkap, dari puluhan jurus tangan kosong, elakan (kelid), hingga teknik serang-balas spesifik yang terstruktur rapi. Selain membangun ketangkasan fisik melalui maenpo, KBPC memegang erat filosofi nama Cimande sebagai "Cai Iman anu Hade" atau Air Iman yang Baik, yang mendidik anggotanya berhati suci. Melalui jaringan keanggotaan yang kokoh, perguruan ini juga berfungsi sebagai wadah silaturahmi, pembinaan mental, dan spiritual yang tak terpisahkan dari nilai-nilai keagamaan. Ribuan pesilat di bawah naungan KBPC secara konsisten menjadikan ilmu bela diri sebagai sarana mendekatkan diri kepada Sang Pencipta sekaligus menjaga kehormatan tradisi leluhur Jawa Barat.</p>', '<p>Aliran Cimande diciptakan dari hasil istikharah para alim ulama seperti Embah Choer pada tahun 1835 dan berkembang pesat di lingkungan pesantren pesisir Sungai Cimande, Bogor. Tradisi yang mulanya diajarkan secara terbatas kepada para santri ini akhirnya dilembagakan menjadi Keluarga Besar Padjadjaran Cimande (KBPC) pada 23 Februari 1962 oleh Guru Besar Kibagus Mochammad Djamhari. Di bawah kepemimpinan para perwira militer seperti Kolonel Djalil Hanafiah dan Brigjen Otjoe Sapri, KBPC melesat hingga memiliki lebih dari 60 cabang di seluruh Indonesia. Tidak hanya berjaya di dalam negeri, ajaran warisan leluhur ini juga sukses menembus ranah internasional dengan merambah benua Amerika, Eropa (Belanda), Timur Tengah, hingga negara-negara di Asia Tenggara. Hingga kini, KBPC berdiri tegak sebagai monumen hidup perjalanan maenpo Cimande yang sukses mendunia tanpa kehilangan jati diri tradisionalnya.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('f3X7DbHwye8dXmEJTn4ceT', 'SANGGAR KESATRIA TEMBONG AGUNG', 'sanggar-kesatria-tembong-agung', 'CIMANDE', 35, 'TAJURHALANG', '/uploads/perguruan-f955dfaba1d0c3414384717fbfd3b5b2b86efb38-1555x1556.png', 'MUHAMMAD FAZAR AZHARI', '6281286196387', '<p>Sanggar Kesatria Tembong Agung (SKTA) adalah entitas pelestari pencak silat yang merepresentasikan keagungan budaya dan karakter kesatria asal wilayah Sumedang. Ajaran di sanggar ini adalah buah perpaduan harmonis antara ketangguhan maenpo aliran Cimande dengan kekayaan "ilmu kesumedangan" yang diwariskan secara eksklusif. Lebih dari sekadar mengajarkan teknik pukulan atau tendangan, SKTA memfokuskan pendidikannya pada pembentukan jati diri, budi pekerti luhur, dan akhlak yang mulia. Filosofinya sangat kental dengan nilai-nilai kearifan lokal, bertujuan untuk mencetak sumber daya manusia (SDM) yang unggul serta memiliki respek tinggi terhadap warisan Nusantara. Dengan metode pengajaran yang humanis dan komprehensif, SKTA terus menjadi kawah candradimuka bagi generasi muda pelestari keaslian peradaban.</p>', '<p>Sejarah berdirinya SKTA tak bisa dilepaskan dari figur Muhammad Fajar Azhari (Kang Oboy), yang terdorong oleh panggilan jiwa untuk menggali kembali akar bela diri leluhurnya. Kang Oboy menyerap langsung kedahsyatan ilmu silat Cimande dari sosok Mang Bejo, lalu mengkombinasikannya dengan ilmu keluarga dari buyut kandungnya, Uyut Subarna (sang pendiri Paguron Gagak Wulung). Untuk menghormati akar historis tempat kelahirannya, sanggar ini dianugerahi nama "Kesatria Tembong Agung", mengambil inspirasi dari kerajaan pertama di Sumedang bentukan Eyang Guru Aji Putih. Penamaan ini bukan sekadar label yang indah, melainkan simbolisasi penghormatan abadi atas perjuangan, keberanian, serta etika kesatria para leluhur yang hingga kini tak lekang ditelan zaman.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('sT1g5mnJOYmdkOwUPhxsna', 'GAGAK LUMAYUNG', 'gagak-lumayung', 'SERA,CIMANDE,SYABANDAR', 75, 'GUNUNG SINDUR', '/uploads/perguruan-f5176d830f5290d779b4a425b927185dc3eb7f8c-1182x1182.jpg', 'TJETJEP JANRA', '62895321343396', '<p>Padepokan Putra Pusaka Wargi Saluyu (Patra Saka Wargi) Gagak Lumayung merupakan lembaga bela diri yang berakar pada tradisi pendekar Jawa Barat dan kini berkembang pesat di wilayah Bogor serta Tangerang Selatan. Di bawah kepemimpinan Abah Tjandra Mukti sejak 2015, perguruan ini berkomitmen melestarikan berbagai aliran pencak silat warisan leluhur bagi generasi masa kini.</p>', '<p>Berdiri bersamaan dengan momentum Konferensi Asia Afrika 1955, P3S Gagak Lumayung lahir dari bersatunya para jawara Jawa Barat dalam membantu TNI dan Polri menjaga keamanan negara. Perjalanan panjang ini berawal dari perguruan P.S Wargi Saluyu yang didirikan Abah Nunu Wisnu pada 1934, hingga kini terus bertransformasi selama tiga generasi untuk menjaga kemurnian budaya bela diri nusantara.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('sT1g5mnJOYmdkOwUPhxtbU', 'GERAK BATIN', 'gerak-batin', 'BETAWI', 50, 'CIPAYUNG', '/uploads/perguruan-0b5e9da500bb41d6e7f17210294fc46fa7e7cab8-1555x1556.png', 'NOVRIZAL ADI SAPUTRO', '628991988585', '<p>PPS Gerak Bathin (GEBATH) adalah perguruan pencak silat yang memadukan ketangkasan bela diri praktis untuk melumpuhkan lawan secara efektif dengan pengolahan spiritual yang mendalam. Fokus utama perguruan ini adalah membentuk pribadi yang tangguh secara fisik sekaligus mampu menjaga hati dari sifat sombong dan hawa nafsu.</p>', '<p>Didirikan pada 9 November 2010 oleh Guru Besar Raden Novrizal Adi Saputro Sangadji, S.E., perguruan ini lahir dengan visi menyelaraskan kekuatan fisik dan kemurnian batin. Sejak awal pembentukannya, GEBATH konsisten mengembangkan teknik bela diri yang efisien sambil terus mengedepankan pembinaan karakter bagi seluruh anggotanya.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('sT1g5mnJOYmdkOwUPhxvAM', 'MACIKA ( MAENPO CIKALONG )', 'macika-maenpo-cikalong', 'CIKALONG', 70, 'CIANJUR', '/uploads/perguruan-45c3cefe7c73290d4b9b754340dab3f3c49c8e9d-1555x1556.png', 'ALM.H. AZIS ASY''ARIE', '6285314208489', '<p>Macika (Maenpo Cikalong) adalah padepokan pencak silat beraliran tradisi Cianjur yang sangat mengutamakan kepekaan "rasa" dalam setiap gerakannya. Berbeda dengan aliran lain, bela diri ini melatih kepekaan sentuhan atau "tempelan" sehingga pesilat mampu merasakan dan mengantisipasi gerakan lawan melalui kontak fisik langsung dengan cepat.</p>', '<p>Aliran ini diciptakan dan dikreasikan oleh Mama Haji Ibrahim pada kurun waktu 1800-an di wilayah Cianjur. Pewarisan ilmu ini terus dijaga ketat dari generasi ke generasi, mulai dari Gan Uweh, Wa Hj. Azis (Alm), hingga saat ini tongkat pelestariannya diteruskan oleh putranya, Prof. Dr. H. Dadan.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('sT1g5mnJOYmdkOwUPhxw48', 'SI KELABANG', 'si-kelabang', 'SENDENG,RAHMAT, SABENI', 55, 'TANAH BANG', '/uploads/perguruan-d67e5a4ad9fbf73bc74bd22d30eea03e1d8b20a5-1555x1556.png', 'MA ASALI NOOR', '6281315017722', '<p>Perguruan Silat Tradisional Si Kelabang hadir sebagai salah satu pusat pertahanan tradisi maen pukul di kawasan Tanah Abang yang kaya akan paduan ilmu beladiri silang daerah. Pada mulanya, kurikulum utamanya adalah kategori mutlak permainan asli Tanah Abang (aliran Kong Rachmad), namun seiring waktu, kekayaan jurusnya ditopang sempurna oleh teknik maut Silat Sendeng Pukul 7 dari Kalimantan (Sintang) dan Gerak Sanalika. Transformasi silat hibrida tradisional ini menciptakan satu sistem pukulan yang agresif, cepat, serta sangat sulit ditebak oleh serangan musuh.</p>', '<p>Merintis jalannya sejak tahun 1986, Si Kelabang berdiri dari titipan sanad ilmu orisinal Kong Rachmad (melalui pewaris Abdusshomad bin Abdul Adzis) yang bermuara tepercaya di tangan Bang Anang (M.A. Osali Noor). Didorong dahaga akan kesempurnaan teknik, Bang Anang tak segan kembali menggali ilmu di tahun 1997 melalui bimbingan tiga figur besar Sendeng—yakni Bang Ambas, Pak Nurdin, dan Bapak Rachman. Puncak elaborasi ini sempurna saat Bang Anang mendalami Gerak Sanalika dari Bang Nunung (Rawa Belong) di tahun 1999, membuktikan Si Kelabang sebagai padepokan silat petarung tulen kaya referensi.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('sT1g5mnJOYmdkOwUPhxxUC', 'TAPAK SUCI', 'tapak-suci', 'SILAT NASIONAL', 150, 'GUNUNG SINDUR', '/uploads/perguruan-af21e4203c224fbcbf9f27c23f6c31402ddbc542-1555x1556.png', 'ARIF RUSMAN', '6281317058504', '<p>Tapak Suci Putera Muhammadiyah (TSPM) adalah perguruan bela diri historis yang bernaung sebagai organisasi otonom independen dan kebanggaan di bawah payung besar Persyarikatan Muhammadiyah. Sangat ikonik di mata publik berkat visualisasi seragam merahnya yang melambangkan keberanian, perguruan ini meramu kekuatan bela diri tangkas dengan fondasi akidah ketauhidan murni. Falsafah sejati seorang kader Tapak Suci terangkum tegas dalam motto penguat jiwanya: "Dengan iman dan akhlak saya menjadi kuat, tanpa iman dan akhlak saya menjadi lemah." Melampaui sebatas sasana melatih pukulan, perguruan mengelola sistem tingkatan kaderisasi berbasis jenjang modern (murid, kader, dan pendekar) yang kompeten serta logis. Melalui pergerakan dakwah kultural berselimut seni gerak, lembaga silat pencetak atlet ini berkomitmen menghadirkan jutaan ksatria Muslim yang pantang menyerah menentang kezaliman di muka bumi.</p>', '<p>Napak tilas akar historis Tapak Suci bisa ditarik kembali bersumber dari eksistensi Pencak Silat Banjaran (1872) asuhan guru K.H. Busyro Syuhada di kawasan Banjarnegara. Rumpun ilmu silat mumpuni ini kemudian hijrah bertumbuh di Kauman, Yogyakarta pada 1925, dan kelak menetaskan tiga kelompok perguruan serumpun (Cikauman, Seranoman, Kasegu). Demi menyelamatkan keutuhan keluarga dan mencegah lahirnya perpecahan padepokan sejalur, para tokoh pesilat yang diorkestrasikan oleh Moh. Barrie Irsyad menempuh ikhtiar mulia untuk menggabungkannya. Tepat di tanggal 31 Juli 1963 (10 Rabiul Awal 1383 H), perguruan gabungan ini secara legal dideklarasikan dengan penunjukan figur Djarnawi Hadikusumo sebagai nakhoda pimpinan pertamanya. Di abad kontemporer ini, Tapak Suci menjulang tak sekadar masuk dalam jajaran sepuluh perguruan perintis pembentukan IPSI, namun juga berkibar menggetarkan medali emas di kejuaraan mancanegara.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('sT1g5mnJOYmdkOwUPhxxfw', 'TROKTOK INDONESIA', 'troktok-indonesia', 'TROKTOK', 50, 'PASANGGRAHAN', '/uploads/perguruan-c52c12f1692372cae45519fa0e8be934d521a53a-1555x1556.png', 'CHAIRUDDIN', '6281398497332', '<p>Troktok Indonesia adalah padepokan pencak silat dinamis dari belahan Jakarta Selatan yang menyebar semangat pengabdian merawat warisan maen pukul dengan memanfaatkan integrasi pelatihan ekstra kurikuler di berbagai institusi sekolah. Dibekali optimisme yang terangkum dalam desain peremajaan kelembagaannya yang solid, komunitas ini sudah jauh bermetamorfosis dari sekadar panggung kreatif menjadi sekolah kepelatihan silat yang profesional dan diminati banyak pemuda.</p>', '<p>Embrio terbentuknya tim tangguh ini mulai bergeliat membumi semenjak hari Selasa, 14 April 2009 dengan menyandang nama pertama "Troktok Sanggar Rumah Kreasi". Usai mendayung melalui perdebatan konstruktif dan sinkronisasi tata kelola dari seluruh jajaran pengurusnya, wajah lembaga tersebut disempurnakan pelafalannya menjadi nama "TROKTOK INDONESIA" untuk memuluskan misinya menjaring pesilat bermental juara.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('yjJTXFEGRRDX55XpLcD4JK', 'GAGAK PUTIH INDONESIA', 'gagak-putih-indonesia', 'CIMANDE', 100, 'TANAH SAREAL', '/uploads/perguruan-92dac5ff006cd90043b1eb0621f00f41fe46ed05-1555x1556.png', 'YUDI WAHYUDI', '6289501541285', '<p>Gagak Putih Indonesia adalah perguruan pencak silat tradisional Nusantara yang berakar kuat di wilayah Jawa Barat sebagai penjaga warisan budaya bela diri lokal. Perguruan ini menjadi wadah pembentukan karakter yang memadukan ketangkasan fisik dengan nilai-nilai luhur kemanusiaan.</p>', '<p>Filosofi nama Gagak Putih Indonesia lahir sebagai simbol kecerdikan, kewaspadaan, dan kesucian niat dalam upaya menegakkan kebenaran melalui seni bela diri. Aliran ini terus berkembang di tanah air dengan membawa misi mulia untuk membela diri sekaligus menjaga kehormatan bangsa.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('yjJTXFEGRRDX55XpLcD66s', 'MERPATI PUTIH', 'merpati-putih', 'SILAT NASIONAL', 50, 'BEJI', '/uploads/perguruan-0ef1e813d1ad96faa0af9a0bc563b2f4d40013e0-1555x1556.png', 'ARIEF PURNAMA', '62818088607255', '<p>Perguruan Pencak Silat Beladiri Tangan Kosong (PPS Betako) Merpati Putih merupakan perguruan berskala nasional yang mengkombinasikan teknik bela diri dengan olah pernapasan khusus. Metode latihan ini dirancang secara sistematis untuk memberikan berbagai manfaat komprehensif, mulai dari kebugaran kesehatan, pertahanan diri yang mematikan, hingga mendukung kebutuhan taktis militer.</p>', '<p>Merpati Putih didirikan secara resmi pada tahun 1963 di Yogyakarta sebagai warisan ilmu leluhur yang terbuka untuk masyarakat luas. Seiring berjalannya waktu, perguruan ini mulai berkembang pesat merambah ibu kota Jakarta sejak tahun 1978 dan kini telah menjadi salah satu perguruan historis terbesar di seluruh Nusantara.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('yjJTXFEGRRDX55XpLcD6Ic', 'PANGLIPUR', 'panglipur', 'SERA,CIMANDE,SYABANDAR', 100, 'KOTA BOGOR SELATAN', '/uploads/perguruan-bb51f74b270dd822e47f2568aafbf09158fc1305-1555x1556.png', 'IMAM FAUZI', '6285215670379', '<p>Perguruan Pencak Silat Panglipur adalah salah satu padepokan historis kebanggaan nusantara yang mensinergikan kelembutan seni gerak dan ketangkasan tarung. Menggabungkan ragam aliran besar Jawa Barat seperti Cimande, Cikalong, Sabandar, Karimadi, hingga Sera, Panglipur berhasil menciptakan harmonisasi gerakan bela diri yang sangat efektif namun tetap indah secara estetika.</p>', '<p>Perguruan bergengsi ini didirikan pada tahun 1909 di Gang Durman, Pasar Baru, Bandung oleh Abah Aleh, seorang maestro silat legendaris kelahiran Banten. Pasca wafatnya sang pendiri pada tahun 1980 di Garut, tongkat kepemimpinan diteruskan dengan gemilang oleh putri keempatnya, Rd. Hj. Enny Rukmini Sekarningrat, yang sukses membawa nama Panglipur meroket hingga diakui dunia internasional.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('yjJTXFEGRRDX55XpLcD6aE', 'SENI MAEN PUKULAN SABENITENABANG', 'seni-maen-pukulan-sabenitenabang', 'SABENI', 25, 'CIPAYUNG JAKARTA TIMUR', '/uploads/perguruan-e9b8fb59228e5ec3684c9cdaffae370e4c24c821-1555x1556.png', 'ALM.ZUL BACTIAR', '6288296450447', '<p>Seni Maen Pukulan Sabeni Tenabang adalah aliran silat asli Betawi dari kawasan Tanah Abang yang dirancang sepenuhnya untuk efektivitas pertarungan nyata, tanpa menggunakan elemen tarian (ngibing). Ciri khas mutlak dari silat ini terletak pada pertarungan jarak rapat dengan gerakan tangan berkecepatan tinggi yang dipadukan secara sinkron dengan teknik sapuan kaki untuk membanting musuh. Karena absennya unsur kembangan, aliran Sabeni mengandalkan prinsip kecepatan maksimum, keluwesan menghindar, dan penyerangan lugas tanpa celah. Kepraktisannya ini menjadikannya salah satu sistem bela diri street-fight paling ditakuti dan sangat dihormati oleh jawara-jawara di seantero wilayah ibu kota. Reputasi kekuatan Sabeni bahkan diakui luas, hingga teknik-tekniknya kerap diadopsi oleh berbagai aliran silat lain sebagai materi pelengkap jurus andalan mereka.</p>', '<p>Ilmu maen pukul mematikan ini diwariskan pertama kali oleh Sabeni bin Canam (1860–1945), tokoh pendekar kharismatik Betawi, yang mulanya menjadikannya sebagai ilmu rahasia internal keluarga besar. Menyadari pentingnya pelestarian dan bekal pertahanan diri anak-anak muda Tanah Abang, keilmuan ini perlahan diajarkan ke masyarakat umum melalui putranya, M. Ali Sabeni. Estafet warisan berharga tersebut kemudian dipegang oleh generasi ketiga, Zul Bachtiar Sabeni, yang mengemban amanah sebagai pewaris tunggal hingga beliau berpulang pada 6 April 2025. Saat ini, nyala obor pelestarian silat Sabeni terus dikobarkan tanpa lelah oleh barisan murid seniornya—di antaranya Ncang Faisal, Bang Guruh, Bang Taufik, dan Bang Benny—dari markas mereka di Kebon Jahe, Tanah Abang.</p>');
INSERT OR REPLACE INTO perguruan (id, name, slug, style, members, location, logo, master_name, contact, description, history) VALUES ('yjJTXFEGRRDX55XpLcD7IG', 'TARUNG BEKSI', 'tarung-beksi', 'BEKSI', 60, 'CISAUK', '/uploads/perguruan-8e65c6afc825a33a861c35a94db4a6c75d2e5ad9-1555x1556.png', 'ROSIKIN', '6285776893577', '<p>Tarung Beksi merupakan wadah silat revolusioner yang mendalami secara spesifik ketangguhan aliran Beksi dari klan Kong H. Hasbullah, dengan konsentrasi pada metode survival dan kerasnya street fight. Berbeda halnya dari yang lain, ruang lingkup pergerakannya juga menyertakan materi penguasaan persenjataan tradisional dalam intensitas pertarungan nyata. Alih-alih tertarik dalam mengejar sistem regulasi kejuaraan prestasi bentukan IPSI, padepokan ini aktif secara nyata menerjunkan pesilatnya pada ajang-ajang laga tarung bebas profesional. Keputusan tersebut tak pelak melabeli Tarung Beksi sebagai patron tangguh pengemban aliran Beksi murni yang lebih memprioritaskan fungsi aplikasi pertahanan fisik absolut daripada medali turnamen.</p>', '<p>Komunitas tarung yang keras ini menyalakan lonceng pendiriannya di lingkup wilayah Kota Tangerang tepat pada kalender 17 Februari 2014 berkat tangan dingin Rosikin, S.Pd.I., atau disapa akrab Bang Bek. Sebagai wujud kesetiaan kepada amanah guru besarnya, Babeh Sabenuh Masir, misi sakral yang dipikulnya adalah merawat keaslian ketangkasan street fight dari Beksi warisan Kong Haji Hasbullah. Dengan spirit kemerdekaan teknik inilah, Tarung Beksi menjaga kegarangan dan nama besar silat hantam Betawi dari ambang degradasi komersialisasi.</p>');
INSERT OR REPLACE INTO news (id, title, slug, date, excerpt, content, image) VALUES ('f85433ac-560e-42d8-99cb-d6dc69675c46', 'KEJUARAAN WORLD PENCAK SILAT WIRALAGA  CHAMPIONSHIP CULTURAL HERITAGE 2026 MALAYSIA', 'kejuaraan-world-pencak-silat-wiralaga-championship-cultural-heritage-2026-malaysia', '2026-01-01', '', '<p>Bismillah, Mohon Doa dan Dukungan! 🙏🏻</p>
<p>Perwakilan PPD SHM Bogor bersama Keluarga Besar Kampung Silat Jampang akan bertanding di ajang dunia World Pencak Silat Wiralaga Championship yang akan diselenggarakan di Malaysia. 🇲🇾🥋</p>
<p>Semoga seluruh perjuangan, latihan, dan persiapan yang telah dilakukan diberikan kelancaran dan kemudahan. Semoga dapat membawa nama baik Indonesia serta mengharumkan nama Kampung Silat Jampang dan Bogor di kancah internasional. 🇮🇩🔥</p>
<p>Mohon doa dan dukungannya.
Semoga Allah SWT senantiasa memberikan kesehatan, keselamatan, kelancaran, dan hasil terbaik.</p>
<p>Bismillah, berjuang dan bertanding!
🇮🇩🥋 Indonesia Jaya!
🤲🏻 Semoga dimudahkan. Aamiin Ya Rabbal ‘Alamiin.</p>', '/uploads/news-bb4c96ecb4abbfbaf2819f73cd502627a5bfc9df-1098x1273.jpg');
INSERT OR REPLACE INTO news (id, title, slug, date, excerpt, content, image) VALUES ('92b4d0ed-e791-4b23-9c7f-b542e32d41e1', 'SHEEVA  HARUMKAN KAMPUNG SILAT JAMPANG Pencak Silat O2SN Provisi Jawa Barat', 'sheeva-putri-basima-harumkan-kampung-silat-jampang-akademi-di-kejuaraan-pencak-silat-o2sn', '2026-07-07', '', '<p>Keberhasilan ini merupakan buah dari kerja keras, disiplin berlatih, serta semangat pantang menyerah yang terus ditunjukkan selama proses pembinaan. Sheeva Putri Basima juga merupakan salah satu anggota KSJ Akademi yang dibina langsung oleh Muhammad Burhan ( Cang Burhan ) selaku pelatih

Semoga langkah Sheeva Putri Basima di tingkat Provinsi Jawa Barat dapat memberikan hasil terbaik, mengharumkan nama sekolah, KSJ Akademi, serta menjadi inspirasi bagi generasi muda untuk terus berprestasi di bidang olahraga, khususnya pencak silat.</p>', '/uploads/news-b48a8a58e874a9652a620a7fe1e3e6ba1c185ed3-1086x1448.jpg');
INSERT OR REPLACE INTO news (id, title, slug, date, excerpt, content, image) VALUES ('5df1b6f7-a0f3-40c5-adf1-d32a47ef9db1', 'Anggota Kampung Silat Jampang Atlet Silek Harimau Minangkabau Bogor Raih Perak di Belgium Open Pencak Silat 2026', 'anggota-kampung-silat-jampang-atlet-silek-harimau-minangkabau-bogor-raih-perak-di-belgium-open', '2026-07-06', '', '<p>Atlet Silek Harimau Minangkabau Bogor Raih Perak di Belgium Open Pencak Silat 2026</p>
<p>SCHOTEN, BELGIA – Atlet nasional Silek (Silat) Harimau Minangkabau Indonesia asal Kabupaten Bogor, Rasya Alteza Ghandi, mengharumkan nama Indonesia di ajang internasional.</p>
<p>Rasya berhasil meraih medali perak pada The 25th Belgium Open Pencak Silat International Championship yang berlangsung 24–26 April 2026 di Schoten, Belgia. Ia berlaga di kategori tanding usia remaja dan berhasil melaju hingga babak final.</p>
<p>Keikutsertaan Rasya merupakan bagian dari kontingen Indonesia yang berjumlah 43 orang. Sebagai atlet binaan INORGA Silek Harimau Minangkabau (SHM) Kabupaten Bogor sekaligus anggota Komunitas Kampung Silat Jampang, prestasinya menjadi bukti kekuatan pembinaan pencak silat di daerah.</p>
<p>Ketua INORGA SHM Kabupaten Bogor, Mohamad Nur Yasin yang akrab disapa Uda Yasin, menyampaikan apresiasi tinggi atas capaian tersebut.</p>
<p>"Apresiasi kepada Atlet Nasional Silat Silek Harimau Minangkabau Indonesia Kabupaten Bogor Rasya Alteza Ghandi bagian dari INORGA KORMI Kabupaten Bogor dan member Komunitas Kampung Silat Jampang masuk final kategori tanding usia remaja berhasil mendapatkan prestasi gemilang memperoleh medali perak," ujarnya.</p>
<p>Menurut Uda Yasin, prestasi ini lebih dari sekadar capaian olahraga. Ia menilai keberhasilan Rasya menjadi representasi nyata kekuatan budaya Indonesia di panggung internasional.</p>
<p>"Melalui Pencak Silat, Indonesia berupaya untuk meningkatkan pemahaman dan apresiasi global terhadap kekayaan warisan budaya Indonesia," tegasnya.</p>
<p>Kehadiran Silek Harimau Minangkabau sebagai INORGA KORMI Kabupaten Bogor di ajang internasional ini diharapkan dapat memotivasi atlet muda lainnya untuk terus berprestasi sekaligus melestarikan warisan budaya bangsa.</p>', '/uploads/news-159c1ec6ed5a21c079741fa57eb8ca5f79bef108-900x1600.jpg');
INSERT OR REPLACE INTO news (id, title, slug, date, excerpt, content, image) VALUES ('b046ef5d-3710-4953-aeb6-fbf6cfdf14a7', '150 Siswa  Kampung Silat Jampang Meriahkan Helaran Hari Jadi Bogor ke-544', '150-siswa-kampung-silat-jampang-meriahkan-helaran-hari-jadi-bogor-ke-544', '2026-06-28', '', '<p><strong>Bogor</strong> – Kampung Silat Jampang (KSJ) turut ambil bagian dalam kemeriahan <strong>Helaran Hari Jadi Bogor (HJB) ke-544</strong> dengan menampilkan <strong>150 pesilat</strong> dari berbagai perguruan yang tergabung dalam KSJ. Penampilan kolosal tersebut menjadi salah satu atraksi budaya yang memukau ribuan masyarakat yang memadati kawasan Alun-Alun Kabupaten Bogor dan sepanjang Jalan Tegar Beriman pada Minggu, 28 Juni 2026. Helaran HJB tahun ini mengusung tema <strong>"Mapag Pajajaran Anyar"</strong> dan menampilkan beragam seni budaya dari seluruh wilayah Kabupaten Bogor.</p>
<p>Dengan penuh semangat, para pesilat menampilkan gerakan dasar pencak silat, jurus tradisi, atraksi kolosal, serta formasi yang menggambarkan kekompakan dan nilai-nilai luhur budaya Sunda. Penampilan tersebut mendapat sambutan hangat dan apresiasi dari masyarakat maupun tamu undangan yang hadir.</p>
<p>Keikutsertaan Kampung Silat Jampang merupakan wujud nyata komitmen dalam mendukung pelestarian pencak silat sebagai warisan budaya bangsa sekaligus memperkenalkan kekayaan seni bela diri tradisional kepada masyarakat luas. Melalui penampilan ini, KSJ juga menunjukkan semangat persatuan yang terbangun dari puluhan perguruan silat yang bersinergi dalam satu wadah.</p>
<p>Ketua Kampung Silat Jampang menyampaikan bahwa partisipasi dalam Hari Jadi Bogor ke-544 bukan sekadar pertunjukan seni, tetapi juga menjadi momentum memperkuat identitas budaya daerah serta menanamkan rasa bangga kepada generasi muda terhadap warisan pencak silat.</p>
<p>"Semoga kehadiran 150 pesilat Kampung Silat Jampang dapat menginspirasi masyarakat untuk terus melestarikan pencak silat sebagai budaya luhur Indonesia, sekaligus mempererat kebersamaan dalam membangun Kabupaten Bogor yang semakin maju dan berbudaya."</p>
<p>Kampung Silat Jampang mengucapkan terima kasih kepada Pemerintah Kabupaten Bogor, seluruh perguruan silat, para pelatih, peserta, relawan, dan seluruh pihak yang telah mendukung sehingga penampilan berjalan dengan lancar dan sukses. KSJ berkomitmen untuk terus menjadi bagian dari pengembangan seni budaya, pembinaan generasi muda, serta pelestarian pencak silat di Kabupaten Bogor.</p>', '/uploads/news-65bfc85e1d306000201747889a81c9f969e7b4c3-1600x917.jpg');
INSERT OR REPLACE INTO news (id, title, slug, date, excerpt, content, image) VALUES ('7d023c0e-68a1-416e-90d4-e97c9835ac86', ' Lebaran Jawara: Kuatkan Persaudaraan, Bawa Silat ke Puncak Kejayaan ', 'lebaran-jawara-kuatkan-persaudaraan-bawa-silat-ke-puncak-kejayaan', '2026-04-25', '', '<p>KABUPATEN BOGOR — Momentum Hari Raya Idulfitri dimanfaatkan komunitas pencak silat di kawasan Jampang, Kabupaten Bogor, untuk mempererat tali persaudaraan sekaligus meneguhkan komitmen pelestarian budaya melalui kegiatan “Lebaran Jawara Kampung Silat Jampang”, Sabtu (25/4/2026).</p>
<p>Mengusung tema “Kuatkan Persaudaraan, Bawa Silat ke Puncak Kejayaan”, kegiatan yang digelar di Aula Masjid Al-Madina, Kawasan Zona Madina ini diikuti sekitar 250 peserta dari 65 aliran silat. Para peserta terdiri atas dewan guru, pendekar, tokoh budaya, serta berbagai komunitas yang tergabung dalam Kampung Silat Jampang.</p>
<p>Ketua Umum Kampung Silat Jampang, Daswara Sulanjana, S.H., menegaskan bahwa Idulfitri menjadi momentum strategis untuk memperkuat silaturahmi sekaligus menjaga eksistensi pencak silat sebagai warisan budaya bangsa.</p>
<p>“Walaupun dengan segala keterbatasan, semangat untuk menjaga dan melestarikan silat tidak boleh surut. Ini adalah warisan leluhur yang harus terus kita jaga bersama,” ujarnya.</p>
<p>Ia menambahkan, kekuatan komunitas silat terletak pada kebersamaan, keikhlasan, serta komitmen dalam membina generasi penerus. Menurutnya, pencak silat tidak hanya berfungsi sebagai bela diri, tetapi juga menjadi sarana pembentukan karakter dan identitas bangsa.</p>
<p>Dalam kesempatan tersebut, Daswara juga memaparkan sejumlah capaian, di antaranya penyelenggaraan Kampung Silat Jampang Championship di GOR Depok yang diikuti lebih dari 1.000 peserta. Ajang tersebut dinilai sebagai bukti bahwa kolaborasi antarperguruan mampu menghadirkan kegiatan berskala besar secara profesional dan aman.</p>
<p>Selain itu, pembinaan atlet terus dilakukan, termasuk melalui keikutsertaan dalam Olimpiade Olahraga Siswa Nasional (O2SN) yang berhasil mengantarkan perwakilan Kampung Silat Jampang meraih prestasi juara pertama.</p>
<p>Kegiatan Lebaran Jawara tidak hanya menjadi ajang silaturahmi, tetapi juga diramaikan dengan pemberian apresiasi kepada pesilat berprestasi serta bazar usaha mikro, kecil, dan menengah (UMKM). Kehadiran bazar diharapkan mampu memberikan dampak ekonomi bagi masyarakat sekitar sekaligus memperkuat peran komunitas silat dalam pemberdayaan ekonomi lokal.</p>
<p>Sementara itu, Executive Director GREAT Edunesia, Mulyadi Saputra, menegaskan komitmennya dalam mendorong pemberdayaan generasi muda melalui pengembangan pencak silat di lingkungan pendidikan. Ia menyampaikan bahwa pihaknya tengah memperluas implementasi pencak silat sebagai kegiatan ekstrakurikuler di sekolah, baik negeri maupun swasta.</p>
<p>“Pencak silat bukan sekadar olahraga, tetapi juga sarana pembentukan karakter, disiplin, dan nilai-nilai kebangsaan. Karena itu, kami ingin menghadirkannya secara lebih luas di dunia pendidikan,” ujarnya.</p>
<p>Menurut Mulyadi, program tersebut telah mulai dijalankan melalui komunikasi dengan berbagai pihak, termasuk lembaga pendidikan dan unsur keagamaan. Ia optimistis kolaborasi lintas sektor akan memperkuat implementasi program di lapangan.</p>
<p>“Kami telah membuka komunikasi dengan sejumlah pihak terkait. Dengan dukungan bersama, kami yakin program ini akan berkembang dan memberikan dampak positif bagi generasi muda,” jelasnya.</p>
<p>Ia juga mengajak seluruh elemen masyarakat, khususnya di Kabupaten Bogor, untuk memperkuat sinergi dalam menjaga dan melestarikan budaya pencak silat.</p>
<p>“Kami mengajak semua pihak untuk terus berkolaborasi, menjaga budaya bangsa, serta mempererat kebersamaan demi masa depan yang lebih baik,” katanya.</p>
<p>Di sisi lain, Kepala Dinas Kebudayaan dan Pariwisata Kabupaten Bogor, Yudi Santosa, menegaskan bahwa upaya pelestarian budaya sekaligus pemberdayaan komunitas terus diperkuat melalui berbagai kegiatan yang melibatkan masyarakat.</p>
<p>Menurutnya, komunitas jawara tidak hanya berperan dalam menjaga seni tradisi, tetapi juga aktif dalam kegiatan sosial dan kolaborasi lintas komunitas, termasuk program kebersihan lingkungan yang rutin dilaksanakan setiap Selasa dan Jumat.</p>
<p>“Kegiatan ini bukan hanya tentang budaya, tetapi juga membangun kesadaran sosial dan menjaga lingkungan,” ujarnya.</p>
<p>Yudi juga menekankan pentingnya kolaborasi dalam pembangunan daerah. Ia menyebut kemajuan Kabupaten Bogor tidak dapat dicapai oleh satu pihak saja, melainkan membutuhkan sinergi seluruh elemen masyarakat.</p>
<p>“Bupati sudah menyampaikan bahwa membangun Bogor tidak cukup oleh satu orang. Harus ada kolaborasi dari semua pihak,” tegasnya.</p>
<p>Sebagai bentuk dukungan konkret, Pemerintah Kabupaten Bogor turut mendorong penguatan pendidikan berbasis kearifan lokal melalui penerapan muatan lokal di tingkat SD dan SMP, termasuk pengenalan sejarah serta budaya daerah. Sekolah juga didorong menyediakan kegiatan ekstrakurikuler seni dan budaya, termasuk pencak silat.</p>
<p>Sementara itu, Staf Ahli Bidang Hubungan Antar Lembaga Kementerian Kebudayaan Prof. Dr. Ismunandar, mengungkapkan bahwa pencatatan budaya di tingkat internasional menjadi langkah penting untuk menjaga keberlangsungan warisan budaya.</p>
<p>Ia menyebut, menteri terkait yang sebelumnya dijadwalkan hadir tidak dapat memenuhi undangan karena tengah menjalankan tugas negara menghadiri pertemuan di UNESCO, Paris, Prancis.</p>
<p>“Pencatatan budaya di UNESCO bertujuan agar warisan budaya tidak hilang. Ini menjadi langkah penting untuk memastikan pencak silat tetap lestari dan dikenal dunia,” ujarnya.</p>
<p>Menurutnya, proses regenerasi pencak silat saat ini menunjukkan perkembangan positif, terlihat dari keterlibatan berbagai kalangan, mulai dari generasi senior hingga anak-anak yang aktif berlatih di berbagai perguruan.</p>
<p>“Melihat generasi muda ikut berlatih dan tampil, saya optimistis budaya besar ini akan terus lestari. Ini menjadi tanggung jawab bersama,” katanya.</p>
<p>Ia menambahkan, upaya memperkenalkan pencak silat ke kancah internasional juga terus dilakukan melalui berbagai pertunjukan budaya di sejumlah negara Eropa pada periode 2021 hingga 2024 sebagai bagian dari diplomasi budaya Indonesia.</p>
<p>Dengan semangat kolaborasi dan pelestarian yang terbangun, komunitas jawara Jampang diharapkan mampu menjadi motor penggerak dalam memperkuat identitas budaya sekaligus membangun kebersamaan masyarakat di Kabupaten Bogor. Para pesilat pun berharap pencak silat dapat terus berkembang dan kembali mencapai puncak kejayaan, baik di tingkat daerah, nasional, maupun internasional. (Hendi)</p>', '/uploads/news-365988387016b22eee4ef213e1cceecbdf24449b-6000x3368.jpg');
INSERT OR REPLACE INTO news (id, title, slug, date, excerpt, content, image) VALUES ('a7673823-22a5-4218-9915-3cf90d808b79', 'Raih Pengakuan UNESCO, KSJ Terima Penghargaan di Ajang Silat Bersholawat', 'raih-pengakuan-unesco-ksj-terima-penghargaan-di-ajang-silat-bersholawat', '2022-06-29', '', '<p>BOGOR — Setelah melangsungkan Pelatihan Eco Enzyme pada Sabtu (23/4/2022), Dompet Dhuafa bersama Kampoeng Silat Jampang (KSJ) melanjutkan giat Pencak Silat Bersholawat di Aula Masjid Al Madinah, Kawasan Zona Madina Dompet Dhuafa, Kemang, Bogor. Berlangsung ba’da sholat Ashar berjamaah, sholawat terlantun khusyuk dipimpin oleh Ustadz Arif Rosyadi (Imam II DKM Al Madinah), bersama Habib Muhammad bin Umar Al-Attos (Pimpinan Majelis Assofa Jakarta), Mayjen TNI (Purn) Eddie Mardjoeki Nalapraya (Dewan Kehormatan), Ustadz Ahmad Shonhaji (Dewan Pembina KSJ &amp; Direktur Budaya, Dakwah, dan Pelayanan Masyarakat), serta Ustadz Herman Budiyanto (Ketua KSJ).</p>
<p>Dalam kesempatan sore itu, Eddie Mardjoeki Nalapraya, memberikan 3 (tiga) piagam penghargaan untuk komunitas pencak silat KSJ, yang secara simbolis diserah-terimakan melalui Ustadz Herman Budiyanto. Penghargaan tersebut antara lain:</p>
<p>Convention for The Safeguarding of The Intangible Culture Heritage bertajuk ‘Traditions of Pencak Silat’ dari UNESCO (12 Desember 2019),</p>
<p>Anugerah Purwakalagrha Indonesia Museum Awards 2021 bertajuk ‘Pengabdian Sepanjang Hayat’ kepada Eddie Mardjoeki Nalapraya dari Komunitas Jelajah Jakarta (19 Desember 2021), dan</p>
<p>Penghormatan kepada Bapak Pencak Silat Dunia dari Ketua IPSI, Letjen TNI (Purn) Prabowo Subianto (13 Desember 2021).</p>
<p>“Penghargaan ini dari UNESCO bertuliskan ‘Traditions of Pencak Silat’, ini pengakuan resmi dunia bahwa pencak silat merupakan tradisional, bukan olahraga saja. Bermula dari inisiasi kita kumpulkan sejarah silat, sehingga keputusan ini dikeluarkan di Kolombia pada tanggal 12 Desember 2019, kemudian diserahkan kepada kedutaan besar kita di Paris, lanjut ke Menlu, lalu ke Menteri Kebudayaan, dan diberikan melalui saya. Tapi penghargaan ini untuk anda, bukan hanya untuk pelaku silat saja tapi untuk seluruh Indonesia,” jelas Bapak Pencak Silat Dunia disela serah-terima penghargaan.</p>
<p>Ia lanjutkan, “Alhamdulillah, seumur saya menjadi Ketua IPSI (Ikatan Pencak Silat Indonesia), baru sekarang saya ketemu acara sholawat bareng pesilat ini. Tapi tidak aneh, sebab prinip pencak silat yang diajarkan oleh nenek moyang kita, pertama itu pendidikan mental, akhlak kita didik. Kedua baru, beladiri itu sendiri, fisik. Jadi akhlak kita tata, jasmani juga segar, aman. Sejatinya latihan beladiri itu untuk kehidupan, bukan untuk berkelahi”.</p>
<p>Habib Muhammad bin Umar Al Attos, dalam tausiyahnya turut menyampaikan, “Jika kita lihat, dengan sholawat itu sejatinya membangkitkan semangat perjuangan. Kembali mencintai Rasul, ruh kita terpantik. Jiwanya bangkitkan, lalu raganya. Benar akhlak harus mendominan, dikedepankan. Sejatinya akhlak yang menguatkan”.</p>
<p>Di akhir acara, Dompet Dhuafa juga menggulirkan ratusan Parsel Ramadhan untuk para pecinta seni budaya beladiri tersebut dan para penerima manfaat di kawasan Zona Madina. Ustadz Herman turut mengungkapkan, “Alhamdulillah, hari ini kita bisa silaturahim seharian bersama untuk mengikuti rangkaian Pelatihan Eco Enzyme, Pencak Silat Bersholawat, dan ditutup dengan Iftar bersama di Zona Madina. Dapat banyak hadiah juga dari Bapak Pencak Silat kita. Harapan kami agar senantiasa mengembangkan budaya silat dan senantiasa beribadah kepada Allah SWT”. (Dompet Dhuafa / Dhika Prabowo)</p>', '/uploads/news-e636bef52b01f05b59b983b28f20278724ff6b2a-1280x852.jpg');
